/**
 * LernStar – PhysicsSim Framework
 * Interaktive Physik-Simulationen mit Live-Diagrammen
 */

'use strict';

// ═══════════════════════════════════════════════════════
// KERN-ENGINE
// ═══════════════════════════════════════════════════════

/* ══════════════════════════════════════════════════════════════════════════
   WELTRAUM-BAUKASTEN

   Gemeinsame Zeichenhilfen fuer die Astronomie-Simulationen. Vorher hatte jede
   ihren eigenen Sternhimmel aus 26 Punkten, verteilt mit (i*89) % W - das ergibt
   ein sichtbares Raster und sieht nach Rechenaufgabe aus, nicht nach Nacht.

   Der Sternhimmel wird EINMAL in ein Offscreen-Canvas gezeichnet und danach nur
   noch kopiert; nur eine Handvoll Sterne funkelt pro Bild neu. Das kostet fast
   nichts und laeuft auch auf einem Schul-Tablet fluessig.
   ══════════════════════════════════════════════════════════════════════════ */

const _WR = { felder: new Map() };

/* Kleiner deterministischer Zufall: gleicher Seed -> gleicher Himmel.
   Ohne das flackert das Sternfeld bei jedem Neuaufbau anders. */
function _wrRnd(seed) {
  let s = seed >>> 0;
  return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
}

/* Sternfeld einmal bauen und merken. dichte = Sterne je 10 000 Pixel. */
function _wrSternfeld(w, h, dichte = 1.1, seed = 7) {
  const key = w + 'x' + h + '/' + dichte + '/' + seed;
  if (_WR.felder.has(key)) return _WR.felder.get(key);
  const cv = document.createElement('canvas');
  cv.width = w; cv.height = h;
  const ctx = cv.getContext('2d');
  const rnd = _wrRnd(seed);
  const n = Math.round(w * h / 10000 * dichte);
  const hell = [];
  for (let i = 0; i < n; i++) {
    const x = rnd() * w, y = rnd() * h;
    // wenige grosse, viele winzige Sterne - das macht die Tiefe aus
    const g = Math.pow(rnd(), 3.2);
    const r = 0.35 + g * 1.9;
    const a = 0.22 + g * 0.72;
    // leichte Farbstreuung: die meisten weiss, einige blaeulich oder gelblich
    const f = rnd();
    const farbe = f > 0.86 ? '188,208,255' : f < 0.1 ? '255,226,180' : '255,255,255';
    ctx.fillStyle = 'rgba(' + farbe + ',' + a.toFixed(3) + ')';
    ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.fill();
    if (g > 0.72) hell.push([x, y, r, farbe]);
  }
  const feld = { cv, hell };
  _WR.felder.set(key, feld);
  return feld;
}

/* Additives Gluehen. Alles, was leuchtet, geht hierueber - dadurch addieren
   sich ueberlappende Lichter, statt sich gegenseitig zu uebermalen. */
function _wrGlanz(ctx, x, y, r, farbe, staerke = 0.85) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0,    'rgba(' + farbe + ',' + staerke + ')');
  g.addColorStop(0.28, 'rgba(' + farbe + ',' + (staerke * 0.42) + ')');
  g.addColorStop(1,    'rgba(' + farbe + ',0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.fill();
  ctx.restore();
}

/* Nachthimmel: Farbverlauf, Sternfeld, Funkeln, Vignette.
   opt.oben / opt.unten setzen die Verlaufsfarben, opt.dichte die Sternzahl. */
function _wrHimmel(ctx, cv, t, opt) {
  opt = opt || {};
  const W = cv.width, H = cv.height;
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, opt.oben  || '#070b1c');
  g.addColorStop(1, opt.unten || '#02030a');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);

  if (opt.sterne !== false) {
    const feld = _wrSternfeld(W, H, opt.dichte || 1.1, opt.seed || 7);
    ctx.drawImage(feld.cv, 0, 0);
    // Funkeln: nur die hellen Sterne, und immer nur ein paar gleichzeitig
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    feld.hell.forEach((s, i) => {
      const f = 0.5 + 0.5 * Math.sin(t * 1.7 + i * 2.399);
      if (f < 0.62) return;
      const a = (f - 0.62) / 0.38;
      ctx.fillStyle = 'rgba(' + s[3] + ',' + (a * 0.75).toFixed(3) + ')';
      ctx.beginPath(); ctx.arc(s[0], s[1], s[2] * (1 + a * 0.8), 0, 6.283); ctx.fill();
      if (a > 0.7) {   // feines Kreuz bei den hellsten
        ctx.strokeStyle = 'rgba(' + s[3] + ',' + (a * 0.3).toFixed(3) + ')';
        ctx.lineWidth = 0.7; const l = s[2] * 4.5;
        ctx.beginPath();
        ctx.moveTo(s[0] - l, s[1]); ctx.lineTo(s[0] + l, s[1]);
        ctx.moveTo(s[0], s[1] - l); ctx.lineTo(s[0], s[1] + l);
        ctx.stroke();
      }
    });
    ctx.restore();
  }
  if (opt.vignette !== false) {
    const v = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.28,
                                       W / 2, H / 2, Math.max(W, H) * 0.72);
    v.addColorStop(0, 'rgba(0,0,0,0)');
    v.addColorStop(1, 'rgba(0,0,0,0.5)');
    ctx.fillStyle = v; ctx.fillRect(0, 0, W, H);
  }
}

/* Himmelskoerper mit Beleuchtung: Der Verlauf sitzt zur Lichtquelle hin
   versetzt, dadurch entsteht der Tag-Nacht-Rand von selbst. */
function _wrKoerper(ctx, x, y, r, farben, opt) {
  opt = opt || {};
  const lx = opt.lx != null ? opt.lx : -0.42;   // Lichtrichtung, -1 .. 1
  const ly = opt.ly != null ? opt.ly : -0.42;
  const g = ctx.createRadialGradient(x + lx * r * 0.75, y + ly * r * 0.75, r * 0.06, x, y, r);
  g.addColorStop(0, farben[0]);
  g.addColorStop(0.55, farben[1] || farben[0]);
  g.addColorStop(1, farben[2] || farben[1] || farben[0]);
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.fill();
  if (opt.saum) {   // Atmosphaerensaum
    _wrGlanz(ctx, x, y, r * 1.55, opt.saum, 0.28);
  }
  if (opt.rand !== false) {
    ctx.strokeStyle = 'rgba(255,255,255,0.14)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.stroke();
  }
}

/* Leuchtender Strahl oder Bahn mit weichem Schein statt harter Linie. */
function _wrSpur(ctx, pkt, farbe, breite = 2.4) {
  if (pkt.length < 2) return;
  ctx.save();
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  ctx.globalCompositeOperation = 'lighter';
  for (const [w, a] of [[breite * 3.4, 0.13], [breite * 1.8, 0.22], [breite, 0.95]]) {
    ctx.strokeStyle = 'rgba(' + farbe + ',' + a + ')';
    ctx.lineWidth = w;
    ctx.beginPath();
    pkt.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]));
    ctx.stroke();
  }
  ctx.restore();
}

/* Beschriftung im Bild: immer mit dunklem Schein hinterlegt, damit sie auf
   jedem Hintergrund lesbar bleibt. */
function _wrText(ctx, x, y, s, opt) {
  opt = opt || {};
  ctx.save();
  ctx.font = opt.font || '10px system-ui, sans-serif';
  ctx.textAlign = opt.align || 'center';
  ctx.lineWidth = 3.2; ctx.strokeStyle = 'rgba(3,5,14,0.85)';
  ctx.lineJoin = 'round';
  ctx.strokeText(s, x, y);
  ctx.fillStyle = opt.farbe || '#dbeafe';
  ctx.fillText(s, x, y);
  ctx.restore();
}

// ═══════════════════════════════════════════════════════
// VOLLBILD - Simulationen fuer den Beamer im Physikraum
//
// Das Problem: Die Leinwaende sind auf 440x250 gebaut, und JEDE der 255
// Zeichenfunktionen rechnet mit festen Pixelwerten dagegen (road = 168,
// carX = 132). Man kann die Leinwand also nicht einfach groesser machen -
// das Bild klebte dann in der Ecke.
//
// Der Ausweg: Die Zeichenfunktionen lesen NUR .width und .height (nachgezaehlt:
// 269 + 255 Zugriffe, sonst nichts). Also bekommen sie weiterhin ihr
// Nennmass zu sehen, waehrend die Leinwand darunter in voller Aufloesung
// liegt und die Grundtransformation den Rest erledigt. Keine einzige
// Simulation muss dafuer angefasst werden.
//
// Dass das traegt, haengt an einer nachgepruefen Eigenschaft des Bestands:
// setTransform und resetTransform kommen NULL Mal vor. Die 14 ctx.scale()
// stehen alle in save/restore-Paaren und komponieren sich sauber mit der
// Grundtransformation. Wer das aendert, macht das Vollbild kaputt.
// ═══════════════════════════════════════════════════════
// Die Beschreiber werden ERST BEIM ERSTEN GEBRAUCH geholt. Beim Laden geht das
// nicht: Die Mini-DOM der Pruefwerkzeuge (simcheck/rauchtest.js, simfakten.js)
// kennt HTMLCanvasElement nicht, und ein Zugriff auf Modulebene liess dort
// jede einzelne Simulation mit "HTMLCanvasElement is not defined" durchfallen -
// nicht nur das Vollbild, sondern der ganze Bestand.
let _CV_W = null, _CV_H = null;
function _cvBeschreiber() {
  if (_CV_W && _CV_H) return true;
  if (typeof HTMLCanvasElement === 'undefined') return false;
  _CV_W = Object.getOwnPropertyDescriptor(HTMLCanvasElement.prototype, 'width');
  _CV_H = Object.getOwnPropertyDescriptor(HTMLCanvasElement.prototype, 'height');
  return !!(_CV_W && _CV_H);
}

function _simSkala(cv, k) {
  if (!cv || !cv.getContext || !_cvBeschreiber()) return;
  if (cv._nomW === undefined) {          // Nennmass einmalig festhalten
    cv._nomW = _CV_W.get.call(cv);
    cv._nomH = _CV_H.get.call(cv);
    // Ab hier sieht jede Zeichenfunktion das Nennmass. Der Setzer schreibt
    // durch - sonst wuerde eine Zuweisung still ins Leere laufen.
    Object.defineProperty(cv, 'width', {
      configurable: true,
      get() { return cv._nomW; },
      set(v) { cv._nomW = v; _simSkala(cv, cv._k || 1); },
    });
    Object.defineProperty(cv, 'height', {
      configurable: true,
      get() { return cv._nomH; },
      set(v) { cv._nomH = v; _simSkala(cv, cv._k || 1); },
    });
  }
  const alt = cv._k || 1;
  if (Math.abs(alt - k) < 1e-6 && cv._skaliert) return;

  // Das Bild geht beim Groessenwechsel verloren. Wer keinen Neuzeichner
  // hinterlegt hat (statische Simulationen, die einmal direkt malen), bekaeme
  // sonst eine leere Flaeche - deshalb vorher sichern und notfalls
  // hochskaliert zurueckblitten. Lieber weich als weg.
  let sicher = null;
  try {
    if (_CV_W.get.call(cv) > 0 && _CV_H.get.call(cv) > 0) {
      sicher = document.createElement('canvas');
      _CV_W.set.call(sicher, _CV_W.get.call(cv));
      _CV_H.set.call(sicher, _CV_H.get.call(cv));
      sicher.getContext('2d').drawImage(cv, 0, 0);
    }
  } catch (e) { sicher = null; }

  _CV_W.set.call(cv, Math.round(cv._nomW * k));   // leert die Leinwand
  _CV_H.set.call(cv, Math.round(cv._nomH * k));
  cv._k = k; cv._skaliert = true;
  const ctx = cv.getContext('2d');
  ctx.setTransform(k, 0, 0, k, 0, 0);

  if (cv._neu) { try { cv._neu(); return; } catch (e) { /* faellt unten auf */ } }
  if (sicher) {                                    // Notnagel: altes Bild dehnen
    ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(sicher, 0, 0, _CV_W.get.call(cv), _CV_H.get.call(cv));
    ctx.restore();
  }
}

// ── TYPOGRAFIE DER DIAGRAMME (14.09.2026) ───────────────────────────────────
//
// Gemeldet von den Schuelern beim Test der Einfuehrungsphase: "konnte bei den
// Diagrammen die Achsen nicht gut lesen", "die Schrift soll groesser und
// dunkler". Nachgemessen war beides begruendet:
//
//   Achsenzahlen  10 px in #94a3b8  =  2,56:1 Kontrast auf Weiss
//   Die Schwelle fuer Text ist 4,5:1; im gedruckten Heft steht Text bei
//   14,68:1. Der Bildschirm war also 5,7-fach schwaecher als das Heft, an dem
//   dieselben Kinder dieselbe Aufgabe loesen.
//
// Die FARBEN gelten fuer alle Diagramme - eine Farbe aendert keine Geometrie.
// Der SCHRIFTGRAD wird nur dort erhoeht, wo die Raender ihn tragen: gemessen
// haben 14 der 47 Zeichner padL >= 56 und padB >= 38, und das sind GENAU die
// 14, die die Grundzeile unten woertlich gleich fuehren (darunter
// _mlabDrawPlot, das alle 13 Messlabore und damit die ganze Einfuehrungsphase
// traegt). Bei den engen Zeichnern liegt padL bei 34 bis 48 - dort liefe eine
// 12-px-Zahl aus dem Diagramm heraus. Sie bleiben bei 10 px und bekommen nur
// die dunklere Farbe.
const _PLOT_TICK_F  = '12px sans-serif';        // Achsenzahlen, war 10 px
const _PLOT_TITEL_F = '700 12px sans-serif';    // Achsenbeschriftung, war 700 10 px
const _PLOT_ZAHL    = '#475569';   //  7,58:1  (war #94a3b8 mit 2,56:1)
const _PLOT_TITEL   = '#1f2937';   // 14,68:1  - die Textfarbe des gedruckten Hefts
const _PLOT_ACHSE   = '#64748b';   //  4,76:1  - Achsen- und Strukturlinien
const _PLOT_GITTER  = '#dbe3ec';   // Gitternetz, etwas kraeftiger als #eef2f7

// ── SCHAERFE IM NORMALEN FENSTER (14.09.2026) ───────────────────────────────
//
// Jede Leinwand traegt ein Nennmass von 420 Bildpunkten Breite und wird per CSS
// auf die Spaltenbreite gedehnt (`.phys-anim-cv { width: 100% }`). Auf einem
// Geraet mit doppelter Punktdichte kommt dieser Faktor noch dazu: Gezeichnet
// wird in 420 Punkte, dargestellt auf 1100 - jede Linie und jede Ziffer
// bekommt also nur ein Drittel der Punkte, die sie braucht.
//
// Im VOLLBILD war das schon geloest (_simVollbildFaktor, gemessen 2,53-fach).
// Im normalen Fenster nicht - deshalb sah es am Beamer scharf aus und auf dem
// Schuelergeraet nicht. Gemeldet haben es die Schueler beim Test der
// Einfuehrungsphase am 14.09.2026: "konnte bei den Diagrammen die Achsen nicht
// gut lesen".
//
// Es ist derselbe Hebel wie beim Vollbild und braucht deshalb dieselbe
// Begruendung: Alle Zeichenfunktionen lesen von der Leinwand NUR .width und
// .height, und die liefern weiterhin das Nennmass (_simSkala legt dafuer einen
// eigenen Getter an). Keine der 226 Simulationen muss angefasst werden.
function _simSchaerfeFaktor(cv) {
  if (!cv || !cv.getBoundingClientRect || !_cvBeschreiber()) return 1;
  const nom = cv._nomW !== undefined ? cv._nomW : _CV_W.get.call(cv);
  if (!nom) return 1;
  const breit = cv.getBoundingClientRect().width;
  if (!breit) return 1;                     // noch nicht im Layout
  const dpr = Math.min((typeof window !== 'undefined' && window.devicePixelRatio) || 1, 2);
  // Gedeckelt auf 4: Mehr bringt dem Auge nichts und kostet Speicher.
  // Unter 1,01 gar nichts tun - dann ist die Leinwand schon passend.
  return Math.max(1, Math.min(4, (breit / nom) * dpr));
}

function _simSchaerfen(el) {
  if (!el || !el.querySelectorAll) return;
  // Erst den Umbruch erzwingen, dann messen - ohne das liefert
  // getBoundingClientRect() auf einem gerade eingehaengten Fenster 0.
  void el.offsetWidth;
  el.querySelectorAll('canvas').forEach(cv => {
    if (cv._voll) return;                   // im Vollbild rechnet _simVollbildFaktor
    const k = _simSchaerfeFaktor(cv);
    if (k > 1.01) _simSkala(cv, k);
  });
}

// Dreht jemand das Tablet oder zieht das Fenster breiter, aendert sich die
// Spaltenbreite - und damit der noetige Faktor. _simSkala tut nichts, wenn er
// gleich bleibt, der Aufruf ist also billig.
if (typeof window !== 'undefined' && window.addEventListener) {
  let _schaerfeWartet = null;
  const _neuSchaerfen = () => {
    if (_schaerfeWartet) clearTimeout(_schaerfeWartet);
    _schaerfeWartet = setTimeout(() => {
      const el = document.getElementById('physModal');
      if (el && !(document.fullscreenElement || document.webkitFullscreenElement))
        _simSchaerfen(el);
    }, 150);
  };
  window.addEventListener('resize', _neuSchaerfen);
  window.addEventListener('orientationchange', _neuSchaerfen);
}

// Wie stark darf vergroessert werden? Der Bildschirm gibt es vor, gedeckelt,
// damit eine 8K-Wand nicht 64-fach Speicher frisst.
function _simVollbildFaktor(box) {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  // Am Nennmass bemessen, nicht an der Kastenbreite: Entscheidend ist, um
  // welchen Faktor die Leinwand WIRKLICH vergroessert dasteht - sonst rechnet
  // man Aufloesung fuer Pixel, die es nicht gibt, oder zu wenig fuer die,
  // die da sind.
  const cv = box && (box.querySelector('.phys-anim-cv') || box.querySelector('canvas'));
  if (cv && cv._nomW) {
    const breit = cv.getBoundingClientRect().width || cv._nomW;
    return Math.max(1, Math.min(6, (breit / cv._nomW) * dpr));
  }
  const breite = (box && box.clientWidth) || window.innerWidth;
  return Math.max(1, Math.min(6, (breite / 760) * dpr));
}

// Im Vollbild wird die Hauptleinwand so gross gemacht, wie sie WIRKLICH passt -
// begrenzt von der Breite UND von der Hoehe. Eine feste Spaltenzahl reicht
// dafuer nicht: Gemessen war die Leinwand bei zwei Spalten 1158x691 auf einem
// 1920x1080-Beamer, also 60 % der Breite. Zieht man sie breiter, schlaegt sofort
// die Hoehe an, und der Knopfstreifen rutscht unter den Bildschirmrand - dann
// sieht die Klasse ein grosses Bild, das niemand mehr bedienen kann.
//
// Deshalb wird angepasst, nicht gerechnet: Startwert so gross wie moeglich,
// dann in wenigen Schritten zuruecknehmen, bis Breite und Bedienung passen.
// Das Seitenverhaeltnis kommt aus dem Nennmass der jeweiligen Simulation -
// die reicht von 1,42 (470x330) bis 1,76 (440x250), eine Zahl im CSS waere
// fuer die Haelfte falsch.
function _simBildAnpassen(el) {
  // Die SICHTBARE Leinwand ist die, an der gemessen wird. lichtuhr bringt acht
  // mit, davon sieben ausgeblendet (Schritte der Herleitung) - und die erste im
  // Dokument ist eine 1x1 grosse Hilfsflaeche. Wer einfach die erste nimmt,
  // rechnet an einer unsichtbaren Leinwand.
  const sichtbar = a => { const r = a.getBoundingClientRect(); return r.width > 1 && r.height > 1; };
  const bilder = Array.prototype.slice.call(el.querySelectorAll('.phys-anim-cv'));
  const cv = bilder.filter(sichtbar)[0] || bilder[0]
          || Array.prototype.slice.call(el.querySelectorAll('canvas')).filter(sichtbar)[0];
  if (!cv || !window.innerHeight) return;
  // Was sichtbar bleiben MUSS, damit die Simulation bedienbar ist: die
  // UNTERSTE Bedienzeile, nicht die erste. Mit querySelector traf es den
  // Regler direkt unter dem Bild - der war sichtbar, der Knopf "Zeit stoppen"
  // darunter aber abgeschnitten. Die Klasse saehe dann ein grosses Bild, das
  // niemand mehr starten kann.
  //
  // Welche Bedienelemente sind wesentlich? Nicht die nach Abstand nahen - ein
  // Pixelfenster zog bei den Messlaboren die Auswertungsknoepfe mit herein und
  // drueckte newton2 auf 617x353. Die Grenze ist inhaltlich: Alles VOR der
  // ersten Abschnittsueberschrift (.fpm-label, z. B. "Messreihe aufnehmen" oder
  // "Auswertung") gehoert zum Bedienen des Bildes, alles danach zur Auswertung
  // und darf unter den Rand rutschen - dorthin scrollt man ohnehin.
  const wesentlich = () => {
    const alle = Array.prototype.slice.call(el.querySelectorAll(
      '.fpm-label, .sim-btn-row, .phys-controls, .phys-ctrl, .lmp-status'));
    const schnitt = alle.findIndex(x => x.classList.contains('fpm-label'));
    return schnitt >= 0 ? alle.slice(0, schnitt) : alle;
  };
  const untenGrenze = () => {
    let u = 0;
    wesentlich().forEach(x => {
      const b = x.getBoundingClientRect();
      if (b.height) u = Math.max(u, b.bottom);
    });
    return u;
  };
  const platzB = () => Math.max(240, el.clientWidth - 48);
  let h = Math.max(220, window.innerHeight - 90);
  for (let i = 0; i < 5; i++) {
    cv.style.width = 'auto';
    cv.style.maxWidth = '100%';
    cv.style.height = Math.round(h) + 'px';
    const r = cv.getBoundingClientRect();
    if (r.width > platzB() + 1) { h *= platzB() / r.width; continue; }
    // Erst das Bild selbst: Es muss immer ganz auf den Schirm. Ohne diese
    // Klammer lief lichtuhr bis y=1101 auf einem 1080er Beamer - unten fehlte
    // ein Stueck. Sie greift, wo es keine Bedienzeile vor der Auswertung gibt
    // und untenGrenze() deshalb nichts liefert.
    const ueberBild = r.bottom - window.innerHeight + 14;
    if (ueberBild > 0) { h = Math.max(220, h - ueberBild); continue; }
    const unten = untenGrenze();
    if (!unten) break;
    const ueber = unten - window.innerHeight + 14;
    if (ueber <= 0) break;
    h = Math.max(220, h - ueber);
  }
  // Dieselbe Hoehe auf ALLE Bildleinwaende: Bei lichtuhr wird beim naechsten
  // Schritt eine andere sichtbar. Jede behaelt ihr eigenes Seitenverhaeltnis
  // (width:auto), maxWidth haelt sie in der Spalte.
  const hoehe = cv.style.height;
  bilder.forEach(b => {
    b.style.width = 'auto'; b.style.maxWidth = '100%'; b.style.height = hoehe;
    b._voll = true;
  });
  cv._voll = true;
}

function _simBildZurueck(el) {
  el.querySelectorAll('canvas').forEach(cv => {
    if (!cv._voll) return;
    cv.style.width = ''; cv.style.height = ''; cv.style.maxWidth = '';
    cv._voll = false;
  });
}

function _simAlleLeinwaende(wurzel, k) {
  (wurzel || document).querySelectorAll('canvas').forEach(cv => _simSkala(cv, k));
}

function _simVollbildAn() {
  const box = document.querySelector('#physModal .sim-box');
  const el  = document.getElementById('physModal');
  if (!el || !box) return;
  const auf = el.requestFullscreen || el.webkitRequestFullscreen;
  if (auf) { try { auf.call(el); } catch (e) { _simVollbildLayout(true); } }
  else _simVollbildLayout(true);          // Browser ohne Vollbild: wenigstens gross
}

function _simVollbildAus() {
  const raus = document.exitFullscreen || document.webkitExitFullscreen;
  if (document.fullscreenElement && raus) { try { raus.call(document); } catch (e) {} }
  else _simVollbildLayout(false);
}

// Der Knopf wird EINMAL zentral eingehaengt, nicht in 255 HTML-Bausteinen.
// Er sitzt links neben dem Schliessen-Kreuz, damit er nicht mit ihm verwechselt
// wird, und traegt Text - ein blosses Symbol haette im Unterricht niemand
// gefunden.
function _simVollbildKnopf(modal) {
  const box = modal && modal.querySelector('.sim-box');
  if (!box || box.querySelector('.sim-voll')) return;
  const b = document.createElement('button');
  b.className = 'sim-voll';
  b.type = 'button';
  b.textContent = '⤢ Vollbild';
  b.title = 'Simulation bildschirmfuellend zeigen';
  b.setAttribute('aria-label', 'Simulation im Vollbild zeigen');
  b.onclick = _simVollbild;
  box.appendChild(b);
}

function _simVollbild() {
  if (document.fullscreenElement || document.getElementById('physModal')?.classList.contains('sim-gross'))
    _simVollbildAus(); else _simVollbildAn();
}

function _simVollbildLayout(an) {
  const el = document.getElementById('physModal');
  if (!el) return;
  const box = el.querySelector('.sim-box');
  el.classList.toggle('sim-gross', !!an);
  const knopf = el.querySelector('.sim-voll');
  if (knopf) {
    knopf.textContent = an ? '⤡ Vollbild verlassen' : '⤢ Vollbild';
    knopf.title = an ? 'Zurueck zur normalen Groesse (Esc)' : 'Simulation bildschirmfuellend zeigen';
  }
  // Erst umbauen lassen, dann messen - sonst steht die alte Breite im Weg.
  // NICHT ueber requestAnimationFrame: Im Hintergrund-Tab feuert es gar nicht,
  // und im kopflosen Browser feuerte es nur beim Hinweg - der Rueckweg blieb
  // dann auf der grossen Leinwand stehen (nachgemessen: Faktor 2,53 statt 1).
  // Ein Lesen von offsetWidth erzwingt den Umbruch hier und jetzt.
  void (box && box.offsetWidth);
  if (an) _simBildAnpassen(el); else _simBildZurueck(el);
  // Erst die Anzeigegroesse, dann die Aufloesung - der Faktor haengt an der
  // Breite, die die Anpassung gerade festgelegt hat.
  // Zurueck aus dem Vollbild NICHT auf 1: Das normale Fenster braucht seinen
  // eigenen Faktor, sonst kaeme man aus dem Vollbild in ein unscharfes Bild.
  if (an) _simAlleLeinwaende(el, _simVollbildFaktor(box));
  else    { _simAlleLeinwaende(el, 1); _simSchaerfen(el); }
  // Beim echten Vollbild setzt sich die Fenstergroesse erst ein Bild spaeter;
  // deshalb ein zweiter Anlauf, der nichts tut, wenn sich nichts geaendert hat.
  if (an && typeof requestAnimationFrame === 'function')
    requestAnimationFrame(() => _simAlleLeinwaende(el, _simVollbildFaktor(box)));
}

// Auch das nur, wenn es ein echtes document gibt - siehe oben.
if (typeof document !== 'undefined' && document.addEventListener) {
  ['fullscreenchange', 'webkitfullscreenchange'].forEach(ev =>
    document.addEventListener(ev, () => {
      if (document.getElementById('physModal'))
        _simVollbildLayout(!!(document.fullscreenElement || document.webkitFullscreenElement));
    }));
}

class PhysicsSimEngine {
  constructor(animId, chartId) {
    this.animCanvas  = document.getElementById(animId);
    this.chartCanvas = document.getElementById(chartId);
    this.actx = this.animCanvas?.getContext('2d');
    this.cctx = this.chartCanvas?.getContext('2d');
    this.data    = {};   // { seriesName: [{t, v}] }
    this.t       = 0;
    this.running = false;
    this.raf     = null;
    this.maxDataPts = 300;
    this.clickT  = null; // für Tangenten-Anzeige
    this._setupChartClick();
  }

  addSeries(name) { this.data[name] = []; }

  record(name, value) {
    if (!this.data[name]) this.data[name] = [];
    this.data[name].push({ t: this.t, v: value });
    if (this.data[name].length > this.maxDataPts)
      this.data[name].shift();
  }

  start(updateFn, animFn, chartCfg, dtMs = 16) {
    this.running = true;
    this.chartCfg = chartCfg;
    // Beim Groessenwechsel wird die Leinwand geleert. Damit _simSkala scharf
    // neu zeichnen kann statt das alte Bild zu dehnen, haengt hier der Weg
    // zurueck zum Zeichner.
    if (this.animCanvas)  this.animCanvas._neu  = () => animFn(this.actx, this.animCanvas);
    if (this.chartCanvas) this.chartCanvas._neu = () => this._drawCharts();
    const loop = () => {
      if (!this.running) return;
      const dt = dtMs / 1000;
      updateFn(dt);
      this.t += dt;
      if (this.actx) animFn(this.actx, this.animCanvas);
      if (this.cctx) this._drawCharts();
      this.raf = requestAnimationFrame(loop);
    };
    this.raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    if (this.raf) cancelAnimationFrame(this.raf);
  }

  reset() { this.data = {}; this.t = 0; this.clickT = null; }

  // ── Diagramm-Rendering ────────────────────────────────
  _drawCharts() {
    const cv = this.chartCanvas;
    const ctx = this.cctx;
    const cfg = this.chartCfg; // [{series, label, unit, color, yMin, yMax}]
    if (!cfg || !cfg.length) return;

    ctx.clearRect(0, 0, cv.width, cv.height);

    const n    = cfg.length;
    const h    = cv.height / n;
    const padL = 54, padR = 12, padT = 24, padB = 18;

    cfg.forEach((c, i) => {
      const y0 = i * h;
      const series = this.data[c.series] || [];

      // Hintergrund
      ctx.fillStyle = i % 2 === 0 ? '#fafafa' : '#f3f4f6';
      ctx.fillRect(0, y0, cv.width, h);

      const gx = padL, gy = y0 + padT;
      const gw = cv.width - padL - padR;
      const gh = h - padT - padB;

      // Gitternetz
      ctx.strokeStyle = '#e5e7eb'; ctx.lineWidth = 1;
      for (let li = 0; li <= 4; li++) {
        const ly = gy + (li / 4) * gh;
        ctx.beginPath(); ctx.moveTo(gx, ly); ctx.lineTo(gx + gw, ly); ctx.stroke();
      }
      for (let li = 0; li <= 5; li++) {
        const lx = gx + (li / 5) * gw;
        ctx.beginPath(); ctx.moveTo(lx, gy); ctx.lineTo(lx, gy + gh); ctx.stroke();
      }

      // Achsen
      ctx.strokeStyle = '#9ca3af'; ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(gx, gy); ctx.lineTo(gx, gy + gh); ctx.lineTo(gx + gw, gy + gh);
      ctx.stroke();

      // Datenkurve
      if (series.length > 1) {
        const tMin = series[0].t;
        const tMax = Math.max(series[series.length - 1].t, tMin + 1);
        const vMin = c.yMin ?? Math.min(...series.map(p => p.v));
        const vMax = c.yMax ?? Math.max(...series.map(p => p.v));
        const vRange = vMax - vMin || 1;

        const tx = t => gx + ((t - tMin) / (tMax - tMin)) * gw;
        const ty = v => gy + gh - ((v - vMin) / vRange) * gh;

        ctx.strokeStyle = c.color || '#7c3aed';
        ctx.lineWidth   = 2;
        ctx.beginPath();
        series.forEach((p, j) => j === 0 ? ctx.moveTo(tx(p.t), ty(p.v)) : ctx.lineTo(tx(p.t), ty(p.v)));
        ctx.stroke();

        // Tangente bei Klick
        if (this.clickT !== null && series.length > 4) {
          const ci = series.findIndex(p => p.t >= this.clickT);
          if (ci > 1 && ci < series.length - 1) {
            const slope = (series[ci + 1].v - series[ci - 1].v) /
                          (series[ci + 1].t - series[ci - 1].t);
            const px = tx(series[ci].t), py = ty(series[ci].v);
            ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2; ctx.setLineDash([6, 3]);
            ctx.beginPath();
            ctx.moveTo(px - 40, py - slope * 40 / gw * gh * (tMax - tMin) / vRange);
            ctx.lineTo(px + 40, py + slope * 40 / gw * gh * (tMax - tMin) / vRange);
            ctx.stroke(); ctx.setLineDash([]);
            // Steigungswert
            ctx.fillStyle = '#ef4444'; ctx.font = '700 11px sans-serif';
            ctx.fillText(`Δ${c.label}/Δt ≈ ${slope.toFixed(2)} ${c.unit}/s`, gx + 2, gy + gh - 4);
          }
        }

        // Achsenbeschriftungen
        ctx.fillStyle = '#374151'; ctx.font = '700 11px sans-serif';
        ctx.fillText(c.label + (c.unit ? ` [${c.unit}]` : ''), gx + 2, gy + 14);
        ctx.fillStyle = '#6b7280'; ctx.font = '10px sans-serif';
        ctx.fillText(vMax.toFixed(1), gx - 4, gy + 12); ctx.textAlign = 'right';
        ctx.fillText(vMin.toFixed(1), gx - 4, gy + gh); ctx.textAlign = 'left';
        ctx.fillText('t [s]', gx + gw - 16, gy + gh + 14);
      }

      // Titel
      ctx.fillStyle = c.color || '#7c3aed'; ctx.font = '700 11px sans-serif';
      ctx.fillText(c.title || (c.label + '-t-Diagramm'), gx + gw / 2 - 40, y0 + 14);
    });
  }

  _setupChartClick() {
    if (!this.chartCanvas) return;
    this.chartCanvas.addEventListener('click', e => {
      const r   = this.chartCanvas.getBoundingClientRect();
      const cx  = (e.clientX - r.left) * (this.chartCanvas.width / r.width);
      const cfg = this.chartCfg?.[0];
      if (!cfg) return;
      const series = this.data[cfg.series] || [];
      if (!series.length) return;
      const tMin = series[0].t, tMax = series[series.length - 1].t;
      const padL = 54, gw = this.chartCanvas.width - padL - 12;
      this.clickT = tMin + ((cx - padL) / gw) * (tMax - tMin);
    });
  }
}

