  'v-formel': { titel: 'Wie berechnet man eine Geschwindigkeit? (v = s / t)', ns: 'vformel', html: () => _vstArbeitsblattHTML() },
  'v-umrechnung': { titel: 'Wie werden m/s und km/h umgerechnet?', ns: 'umrechnung', html: () => _umrArbeitsblattHTML() },
