    ctx.beginPath(); ctx.moveTo(X(e), ya); ctx.lineTo(X(e), ya + 26 + (i % 2) * 13); ctx.stroke();
    ctx.fillStyle = '#94a3b8'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText(mk.n, X(e), ya + 36 + (i % 2) * 13);
