// ═══════════════════════════════════════════════════════
// 5.3.4  WOVON HÄNGT DIE GRÖSSE DES SCHATTENS AB?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Licht und Schall"
// Handlungsorientiert: Punktlichtquelle (Lampe), Gegenstand, Schirm.
// Schattengröße B = G · b / a  (Strahlensatz).
//   • Schirm verschieben (a fest)     → B ~ b      (Ursprungsgerade)
//   • Gegenstand verschieben (b fest)  → B ~ 1/a    (fallende Kurve)
// Nur eine Größe verändern, die andere bleibt gleich.
// Darunter: Arbeitsblatt (Realschule-Struktur) + Minidiagnose +
// Lehrkraftbereich, geschützt durch das Passwort-Gate (0123).
// ═══════════════════════════════════════════════════════

const _SHA_G = 4;          // Gegenstandshöhe in cm (fest)
const _SHA_A_FIX = 20;     // Abstand Lampe→Gegenstand, wenn der Schirm bewegt wird
const _SHA_B_FIX = 60;     // Abstand Lampe→Schirm, wenn der Gegenstand bewegt wird
let _sha = null;

function _shaB(a, b) { return _SHA_G * b / a; }   // Strahlensatz

const _SHA_CFG = {
  schirm:     { min: 30, max: 90, step: 10, val: 60, lbl: 'Schirmabstand b', unit: 'cm', marks: [30, 40, 50, 60, 70, 80] },
  gegenstand: { min: 10, max: 50, step: 5,  val: 20, lbl: 'Gegenstandsabstand a', unit: 'cm', marks: [10, 15, 20, 30, 40, 50] }
};

const _SHA_PRESETS = [
  // Preset 0 – Schirm verschieben: B über b (Ursprungsgerade)
  { tab: 'Schirm b → Schatten B',
    xl: 'Schirmabstand b in cm', yl: 'Schattengröße B in cm',
    x: r => r.mode === 'schirm' ? r.b : NaN, y: r => r.B, grp: r => r.a,
    gl: k => 'Gegenstand fest bei a = ' + _fpmNum(+k, 0) + ' cm', slope: k => _SHA_G / +k,
    col: (k, i) => _MLAB_PALETTE[i % _MLAB_PALETTE.length],
    curveFn: (xv, k) => _SHA_G / +k * xv,
    note: 'Ursprungsgerade ⇒ B ~ b. Je weiter der Schirm weg ist, desto größer der Schatten – und zwar: doppelter Abstand = doppelt so großer Schatten. Die Steigung der Geraden ist G/a.',
    typ: 'proportionale Funktion (Ursprungsgerade)', form: 'B = (G / a) · b',
    param: () => 'Steigung = G/a = ' + _fpmNum(_SHA_G / _SHA_A_FIX, 2) + '  (G = ' + _SHA_G + ' cm, a = ' + _SHA_A_FIX + ' cm)',
    term: () => (_SHA_G / _SHA_A_FIX).toString() + '*x',
    deutung: 'Der Schatten wächst gleichmäßig mit dem Schirmabstand. Verdoppelst du b, verdoppelt sich B.',
    ergebnis: (g0) => _mlabErgebnis('Steigung G/a aus der Ausgleichsgeraden',
      _fpmNum(g0.fit.k, 3), '', _fpmNum(_SHA_G / (+g0.key), 3), 'B = G·b/a  ⇒  Steigung = G/a = ' + _SHA_G + '/' + _fpmNum(+g0.key, 0)) },
  // Preset 1 – Gegenstand verschieben: B über a (fallende Kurve, qualitativ)
  { tab: 'Gegenstand a → Schatten B',
    xl: 'Gegenstandsabstand a in cm', yl: 'Schattengröße B in cm',
    x: r => r.mode === 'gegenstand' ? r.a : NaN, y: r => r.B, grp: r => r.b,
    gl: k => 'Schirm fest bei b = ' + _fpmNum(+k, 0) + ' cm', curve: true,
    col: (k, i) => _MLAB_PALETTE[(i + 1) % _MLAB_PALETTE.length],
    curveFn: (xv, k) => _SHA_G * (+k) / xv,
    note: 'Keine Gerade, sondern eine fallende Kurve: B ~ 1/a. Je näher der Gegenstand an der Lampe steht (a klein), desto größer der Schatten. Ganz nah an der Lampe wird der Schatten riesig.',
    typ: 'fallende Kurve (je näher, desto größer)', form: 'B = G · b / a',
    param: () => 'b fest = ' + _SHA_B_FIX + ' cm,  G = ' + _SHA_G + ' cm',
    term: () => (_SHA_G * _SHA_B_FIX).toString() + '/x',
    deutung: 'Rückt der Gegenstand zur Lampe (a klein), wird der Schatten groß. Rückt er zum Schirm (a groß), wird der Schatten klein.' }
];

function _shaInit() {
  _sha = {
    mode: 'schirm', a: _SHA_A_FIX, b: _SHA_B_FIX, flash: 0,
    rows: [], nextId: 1, preset: 0, fn: null, fnAuto: false, origin: true, showTheory: false,
    pre: 'sha', plotId: 'shaPlot', fitId: 'shaFit', fnId: 'shaFn', fnErrId: 'shaErr', theoId: 'shaTheo',
    presets: _SHA_PRESETS
  };
}

function _shaHTML() {
  const c = _SHA_CFG[_sha.mode];
  const varVal = _sha.mode === 'schirm' ? _sha.b : _sha.a;
  return `<div class="sim-box sim-box-wide fpm-sim sha-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🔦 Wovon hängt die Größe des Schattens ab?</h3>
    <div class="fpm-note" style="margin-top:2px">Die Taschenlampe steht fest auf der Holzkiste, davor haengt der handgrosse Pappwolf, dahinter ist die Bretterwand. <b>Veraendere nur einen Abstand</b> und miss, wie hoch der Schatten wird.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="shaAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn${_sha.mode === 'schirm' ? ' primary' : ''}" id="shaMode0" onclick="_shaSetMode('schirm')">🧱 Bretterwand verschieben</button>
          <button class="sim-btn${_sha.mode === 'gegenstand' ? ' primary' : ''}" id="shaMode1" onclick="_shaSetMode('gegenstand')">🐺 Pappwolf verschieben</button>
        </div>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label"><b id="shaVarName">${c.lbl}</b>: <b id="shaVarLbl">${_fpmNum(varVal, 0)} cm</b></span>
          <input type="range" id="shaVar" min="${c.min}" max="${c.max}" step="${c.step}" value="${varVal}"
            oninput="_shaSetVar(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-note" style="margin-top:4px">Aktuelle Schattengröße: <b id="shaBLbl">B = ${_fpmNum(_shaB(_sha.a, _sha.b), 1)} cm</b> &nbsp;·&nbsp; Gegenstand G = ${_SHA_G} cm (immer gleich)</div>
      </div>
      <div>
        <div class="fpm-label">Messung – Abstand einstellen, dann Messwert übernehmen</div>
        <div class="sim-btn-row">
          <button class="sim-btn primary" onclick="_shaMessen()">＋ Messwert übernehmen</button>
          <button class="sim-btn" onclick="_shaDemo()">📋 Beispielmessreihe</button>
          <button class="sim-btn" onclick="_shaClear()">🗑 Tabelle leeren</button>
        </div>
        <div class="fpm-tablewrap">
          <table class="sim-table">
            <thead><tr><th>Lampe → Pappwolf (cm)</th><th>Lampe → Wand (cm)</th><th>Hoehe des Schattens (cm)</th><th></th></tr></thead>
            <tbody id="shaTbody"></tbody>
          </table>
          <div class="fpm-empty" id="shaEmpty">Noch keine Messwerte.<br>Abstand einstellen → „Messwert übernehmen".</div>
        </div>
      </div>
    </div>
    <div class="fpm-label" style="margin-top:12px">Auswertung – trage die Schattengröße B über den veränderten Abstand auf</div>
    ${_mlabAuswertungHTML(_sha, { preset: '_shaSetPreset', setfn: '_shaSetFn', theo: '_shaTheorieFn', clear: '_shaClearFn', bool: '_shaSetBool' })}
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>B = G · b / a</b> &nbsp;|&nbsp; Schirm weiter weg → größer &nbsp;|&nbsp; Gegenstand näher an der Lampe → größer
    </p>
    ${_shaArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _shaSetVar(v) {
  if (_sha.mode === 'schirm') _sha.b = +v; else _sha.a = +v;
  const el = document.getElementById('shaVarLbl'); if (el) el.textContent = _fpmNum(+v, 0) + ' cm';
  const bl = document.getElementById('shaBLbl'); if (bl) bl.textContent = 'B = ' + _fpmNum(_shaB(_sha.a, _sha.b), 1) + ' cm';
}
function _shaSwitch(mode, preset) {
  if (mode !== _sha.mode && _sha.rows.length &&
      !confirm('Für eine neue Messreihe wird die Tabelle geleert. Fortfahren?')) {
    // Ablehnung: Oberfläche auf aktuellen Modus zurücksetzen
    for (let k = 0; k < _sha.presets.length; k++)
      document.getElementById('shaTab' + k)?.classList.toggle('on', k === _sha.preset);
    return;
  }
  if (mode !== _sha.mode) { _sha.rows = []; _shaRenderTable(); }
  _sha.mode = mode;
  const c = _SHA_CFG[mode];
  _sha.a = mode === 'schirm' ? _SHA_A_FIX : c.val;
  _sha.b = mode === 'schirm' ? c.val : _SHA_B_FIX;
  document.getElementById('shaMode0')?.classList.toggle('primary', mode === 'schirm');
  document.getElementById('shaMode1')?.classList.toggle('primary', mode === 'gegenstand');
  const sl = document.getElementById('shaVar');
  if (sl) { sl.min = c.min; sl.max = c.max; sl.step = c.step; sl.value = c.val; }
  const nm = document.getElementById('shaVarName'); if (nm) nm.textContent = c.lbl;
  const lb = document.getElementById('shaVarLbl'); if (lb) lb.textContent = _fpmNum(c.val, 0) + ' cm';
  const bl = document.getElementById('shaBLbl'); if (bl) bl.textContent = 'B = ' + _fpmNum(_shaB(_sha.a, _sha.b), 1) + ' cm';
  _mlabSetPreset(_sha, preset);
}
function _shaSetMode(m) { _shaSwitch(m, m === 'schirm' ? 0 : 1); }
function _shaMessRow(mode, a, b) {
  const Bt = _shaB(a, b) * (1 + (Math.random() - 0.5) * 0.02);   // kleine Ablese-Streuung
  return { mode, a, b, B: Math.round(Bt * 10) / 10 };
}
function _shaMessen() {
  const r = _shaMessRow(_sha.mode, _sha.a, _sha.b);
  _shaAddRow(r); _sha.flash = 1;
}
function _shaDemo() {
  const c = _SHA_CFG[_sha.mode];
  c.marks.forEach(m => {
    const a = _sha.mode === 'schirm' ? _SHA_A_FIX : m;
    const b = _sha.mode === 'schirm' ? m : _SHA_B_FIX;
    const r = _shaMessRow(_sha.mode, a, b);
    _sha.rows.push({ id: _sha.nextId++, mode: r.mode, a: r.a, b: r.b, B: r.B });
  });
  _shaRenderTable(); _mlabDrawPlot('shaPlot', _sha);
}
function _shaAddRow(r) {
  _sha.rows.push({ id: _sha.nextId++, mode: r.mode, a: r.a, b: r.b, B: r.B });
  _shaRenderTable(); _mlabDrawPlot('shaPlot', _sha);
}
function _shaDelRow(id) { _sha.rows = _sha.rows.filter(r => r.id !== id); _shaRenderTable(); _mlabDrawPlot('shaPlot', _sha); }
function _shaClear() {
  if (_sha.rows.length && !confirm('Alle ' + _sha.rows.length + ' Messwerte löschen?')) return;
  _sha.rows = []; _shaRenderTable(); _mlabDrawPlot('shaPlot', _sha);
}
function _shaRenderTable() {
  const tb = document.getElementById('shaTbody'); if (!tb) return;
  const empty = document.getElementById('shaEmpty');
  if (empty) empty.style.display = _sha.rows.length ? 'none' : 'block';
  tb.innerHTML = _sha.rows.map((r, i) => {
    const col = _MLAB_PALETTE[(_sha.mode === 'schirm' ? 0 : 1)];
    const varCell = r.mode === 'schirm' ? 'b' : 'a';
    return `<tr>
       <td${varCell === 'a' ? ' class="sha-var"' : ''}>${varCell === 'a' ? '<span class="fpm-dot" style="background:' + col + '"></span>' : ''}${_fpmNum(r.a, 0)}</td>
       <td${varCell === 'b' ? ' class="sha-var"' : ''}>${varCell === 'b' ? '<span class="fpm-dot" style="background:' + col + '"></span>' : ''}${_fpmNum(r.b, 0)}</td>
       <td><b>${_fpmNum(r.B, 1)}</b></td>
       <td class="fpm-del" onclick="_shaDelRow(${r.id})" title="löschen">✕</td></tr>`;
  }).join('');
}

// ── Wiring zum Framework ───────────────────────────────
function _shaSetPreset(i) { _shaSwitch(i === 0 ? 'schirm' : 'gegenstand', i); }
function _shaSetFn(s) { _mlabSetFn(_sha, s); }
function _shaTheorieFn() { _mlabTheorieFn(_sha); }
function _shaClearFn() { _mlabClearFn(_sha); }
function _shaSetBool(k, v) { _sha[k] = v; _mlabDrawPlot('shaPlot', _sha); }

// ── Animation ──────────────────────────────────────────
function _shaUpdate(dt) { if (_sha) _sha.flash = Math.max(0, _sha.flash - dt * 1.5); }
function _shaDraw(ctx, cv) {
  if (!_sha) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, W, H);   // dunkler Raum
  const axisY = H / 2 - 4;
  const xL = 44;                       // Lampe (Punktlichtquelle)
  const pxX = (W - 70) / 100;          // 100 cm passen in die Breite
  const vs = 4.2;                      // px pro cm (senkrecht)
  const a = _sha.a, b = _sha.b, B = _shaB(a, b);
  const xObj = xL + a * pxX, xScr = xL + b * pxX;
  const halfG = (_SHA_G / 2) * vs;
  const halfB = Math.min((B / 2) * vs, H / 2 - 14);
  const yTopO = axisY - halfG, yBotO = axisY + halfG;
  const yTopS = axisY - halfB, yBotS = axisY + halfB;

  // Lichtkegel (schwaches Gelb)
  ctx.fillStyle = 'rgba(253,224,71,0.10)';
  ctx.beginPath(); ctx.moveTo(xL, axisY);
  ctx.lineTo(xScr, axisY - halfB * 2.4); ctx.lineTo(xScr, axisY + halfB * 2.4); ctx.closePath(); ctx.fill();

  // Schattenkegel (hinter dem Gegenstand)
  ctx.fillStyle = 'rgba(15,23,42,0.85)';
  ctx.beginPath(); ctx.moveTo(xObj, yTopO); ctx.lineTo(xScr, yTopS);
  ctx.lineTo(xScr, yBotS); ctx.lineTo(xObj, yBotO); ctx.closePath(); ctx.fill();

  // Grenz-Lichtstrahlen (gelb)
  ctx.strokeStyle = '#fde047'; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(xL, axisY); ctx.lineTo(xScr, yTopS); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(xL, axisY); ctx.lineTo(xScr, yBotS); ctx.stroke();

  // Schirm
  ctx.fillStyle = '#e2e8f0';
  ctx.beginPath(); ctx.roundRect ? ctx.roundRect(xScr, axisY - 62, 8, 124, 3) : ctx.rect(xScr, axisY - 62, 8, 124); ctx.fill();
  // Schatten auf dem Schirm
  ctx.fillStyle = _sha.flash > 0.3 ? '#f97316' : '#1e293b';
  ctx.fillRect(xScr, yTopS, 8, Math.max(2, yBotS - yTopS));

  // Gegenstand (undurchsichtig)
  ctx.fillStyle = '#7c3aed';
  ctx.beginPath(); ctx.roundRect ? ctx.roundRect(xObj - 5, yTopO, 10, yBotO - yTopO, 2) : ctx.rect(xObj - 5, yTopO, 10, yBotO - yTopO); ctx.fill();

  // Lampe
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.arc(xL, axisY, 7, 0, 2 * Math.PI); ctx.fill();
  ctx.strokeStyle = '#fde047'; ctx.lineWidth = 1.4;
  for (let k = 0; k < 8; k++) { const an = k * Math.PI / 4; ctx.beginPath(); ctx.moveTo(xL + Math.cos(an) * 9, axisY + Math.sin(an) * 9); ctx.lineTo(xL + Math.cos(an) * 13, axisY + Math.sin(an) * 13); ctx.stroke(); }

  // Beschriftung Abstände
  ctx.strokeStyle = '#64748b'; ctx.lineWidth = 1; ctx.setLineDash([3, 3]);
  ctx.beginPath(); ctx.moveTo(xL, axisY + 66); ctx.lineTo(xObj, axisY + 66); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(xL, axisY + 82); ctx.lineTo(xScr, axisY + 82); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = '#cbd5e1'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('a = ' + _fpmNum(a, 0) + ' cm', (xL + xObj) / 2, axisY + 63);
  ctx.fillText('b = ' + _fpmNum(b, 0) + ' cm', (xL + xScr) / 2, axisY + 96);
  // B-Label am Schirm
  ctx.fillStyle = '#fca5a5'; ctx.textAlign = 'left';
  ctx.fillText('B = ' + _fpmNum(B, 1) + ' cm', Math.min(xScr + 12, W - 70), axisY);
  // Legende
  ctx.fillStyle = '#facc15'; ctx.textAlign = 'left'; ctx.font = '700 10px sans-serif';
  ctx.fillText('Lampe', xL - 16, axisY - 16);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.3.4 (Realschule-Struktur) + Minidiagnose + Lehrkraft
// Alles im Passwort-Gate (0123). ns = 'schatten'.
// ═══════════════════════════════════════════════════════
function _shaArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('schatten')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('schatten')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wovon hängt die Größe eines Schattens ab?</b> Du hast eine Lampe, einen Gegenstand und einen Schirm. Finde durch Ausprobieren heraus, wann der Schatten groß und wann er klein wird.</div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        <div class="ab-t">Kreuze an oder schreibe auf: Was glaubst du, macht den Schatten <b>größer</b>?</div>
        ${ta('v1', 'Ich vermute: Der Schatten wird größer, wenn …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung (Versuch 1: Schirm verschieben)</div>
        <ol class="ab-ol">
          <li>Stelle oben den Modus <b>„Schirm verschieben"</b> ein.</li>
          <li>Schiebe den Schirm auf <b>30 cm</b>. Lies die Schattengröße <b>B</b> ab und drücke <b>„Messwert übernehmen"</b>.</li>
          <li>Wiederhole das für <b>40, 50, 60, 70, 80 cm</b>. Der Gegenstand bleibt die ganze Zeit <b>gleich</b> (a = 20 cm).</li>
          <li>Öffne unten die Auswertung und trage <b>B über b</b> auf.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle (Versuch 1)</div>
        <table class="ab-table"><tbody>
          <tr><td>Schirmabstand b (cm)</td><td>30</td><td>40</td><td>50</td><td>60</td><td>70</td><td>80</td></tr>
          <tr><td>Schattengröße B (cm)</td><td>${inp('t1_1', '')}</td><td>${inp('t1_2', '')}</td><td>${inp('t1_3', '')}</td><td>${inp('t1_4', '')}</td><td>${inp('t1_5', '')}</td><td>${inp('t1_6', '')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Durchführung (Versuch 2: Gegenstand verschieben)</div>
        <ol class="ab-ol">
          <li>Stelle den Modus <b>„Gegenstand verschieben"</b> ein (der Schirm bleibt jetzt fest bei b = 60 cm).</li>
          <li>Schiebe den Gegenstand auf <b>10, 20, 30, 40, 50 cm</b> und übernimm jeweils den Messwert.</li>
        </ol>
        <table class="ab-table"><tbody>
          <tr><td>Gegenstandsabstand a (cm)</td><td>10</td><td>20</td><td>30</td><td>40</td><td>50</td></tr>
          <tr><td>Schattengröße B (cm)</td><td>${inp('t2_1', '')}</td><td>${inp('t2_2', '')}</td><td>${inp('t2_3', '')}</td><td>${inp('t2_4', '')}</td><td>${inp('t2_5', '')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">6 · Skizze</div>
        <div class="ab-t">Zeichne Lampe, Gegenstand, Schirm und den Schatten. Zeichne auch die beiden Lichtstrahlen ein, die den Schatten begrenzen.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">7 · Auswertung</div>
        <ol class="ab-ol">
          <li>Versuch 1: Wie liegen die Punkte im Diagramm? ${inp('a1', 'z. B. auf einer Geraden …')}</li>
          <li>Was passiert mit B, wenn du den Schirmabstand b <b>verdoppelst</b> (z. B. von 40 auf 80 cm)? ${inp('a2', '')}</li>
          <li>Versuch 2: Wird der Schatten größer, wenn der Gegenstand <b>näher an die Lampe</b> rückt? ${inp('a3', 'ja / nein, weil …')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">8 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Der Schatten wird <b>größer</b>, wenn der Schirm ${inp('m1', 'näher / weiter …')} von der Lampe entfernt ist.<br>
        Der Schatten wird auch größer, wenn der Gegenstand ${inp('m2', 'näher / weiter …')} an der Lampe steht.<br>
        Verdoppelt man den Schirmabstand, so wird der Schatten ${inp('m3', 'wie groß?')}.</div></div>

      <div class="ab-sec"><div class="ab-h">9 · Transfer (Alltag)</div>
        <div class="ab-t">Beim Schattentheater willst du eine <b>riesige</b> Figur an die Wand werfen. Wo stellst du die Figur hin – nah an die Lampe oder nah an die Wand? Begründe.</div>
        ${ta('tr1', 'Ich stelle die Figur … , weil …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="shaMini">${_shaMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich? Klicke an:</div>
        <div class="sha-self" id="shaSelf">
          <button class="sim-btn" onclick="_shaSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_shaSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_shaSelf(3)">😃 sicher</button>
          <span id="shaSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="shaSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Versuch 1 (a = 20 cm): B = 6 · b/30-Werte → 6; 8; 10; 12; 14; 16 cm. Die Punkte liegen auf einer <b>Ursprungsgeraden</b> (kleine Messstreuung). Versuch 2 (b = 60 cm): a = 10→24; 20→12; 30→8; 40→6; 50→4,8 cm → <b>fallende Kurve</b>.</div>
        <div class="ab-t"><b>Fachlich richtige Auswertung.</b> Strahlensatz: B = G · b/a mit G = 4 cm. Versuch 1: B ∝ b (Steigung G/a = 4/20 = 0,2) → doppelter Schirmabstand = doppelte Schattengröße. Versuch 2: B ∝ 1/a → je näher der Gegenstand an der Lampe, desto größer der Schatten.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Der Schatten ist genauso groß wie der Gegenstand." (2) „Ein größerer Abstand macht den Schatten kleiner." (3) Verwechslung: näher zum Schirm ↔ näher zur Lampe. (4) „Bei Sonne (großer Abstand) gäbe es keinen Halbschatten" – hier bewusst Punktlichtquelle.</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Zwei Grenzstrahlen von der Lampe über Ober- und Unterkante des Gegenstands einzeichnen lassen; Strahlensatz als „Fächer" veranschaulichen; erst nur EINEN Abstand verändern lassen.</div>
        <div class="ab-t"><b>Musterlösung Merksatz.</b> weiter · näher · doppelt so groß. <b>Transfer:</b> Figur nah an die Lampe (kleines a) → größter Schatten. <b>Minidiagnose:</b> 1 → „wird größer"; 2 → „24 cm"; 3 → „nah an die Lampe".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('schatten')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('schatten', 'Wovon hängt die Größe des Schattens ab?', body);
}

// ── Minidiagnose (3 Aufgaben mit Rückmeldung) ──────────
const _SHA_MINI = [
  { q: '1. Du schiebst den Schirm weiter von der Lampe weg. Was passiert mit dem Schatten?',
    opts: ['Er wird kleiner', 'Er bleibt gleich', 'Er wird größer'],
    correct: 2,
    fb: ['Fast! Probiere es in der Simulation: Schieb den Schirm nach rechts – der Schatten wird tatsächlich größer.',
         'Schau genau hin: Der Schatten ändert sich sehr wohl, wenn du den Schirm verschiebst.',
         'Richtig! Schirm weiter weg = größerer Schatten.'] },
  { q: '2. Der Schirm ist 60 cm weg, der Schatten ist 12 cm groß. Du schiebst den Schirm auf 120 cm (doppelt so weit). Wie groß ist der Schatten dann etwa?',
    opts: ['6 cm', '12 cm', '24 cm'],
    correct: 2,
    fb: ['Andersherum: Bei größerem Abstand wird der Schatten größer, nicht kleiner.',
         'Der Abstand ändert sich ja – dann bleibt der Schatten nicht gleich.',
         'Richtig! Doppelter Abstand → doppelt so großer Schatten: 24 cm.'] },
  { q: '3. Du willst mit einer Taschenlampe einen möglichst großen Schatten deiner Hand an die Wand werfen. Was tust du?',
    opts: ['Hand nah an die Wand halten', 'Hand nah an die Lampe halten', 'Die Lampe ausschalten'],
    correct: 1,
    fb: ['Nah an der Wand wird der Schatten klein (fast so groß wie die Hand). Versuch das Gegenteil.',
         'Richtig! Nah an der Lampe (kleines a) → riesiger Schatten.',
         'Ohne Licht gibt es gar keinen Schatten 🙂'] }
];
function _shaMiniHTML() {
  return _SHA_MINI.map((m, qi) =>
    `<div class="sha-q">
       <div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_shaAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="shaFb${qi}"></div>
     </div>`).join('');
}
function _shaAns(qi, oi) {
  const m = _SHA_MINI[qi];
  const el = document.getElementById('shaFb' + qi);
  if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi];
  el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _shaSelf(n) {
  const out = document.getElementById('shaSelfOut');
  const val = document.getElementById('shaSelfVal');
  if (val) { val.value = String(n); _abSave('schatten'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen weiter.' : 'Frag deine Lehrkraft um Hilfe – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.1.1  WELCHE STOFFE WERDEN VON EINEM MAGNETEN ANGEZOGEN?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Strom und Magnetismus"
// Handlungsorientiert: der Schüler hält nacheinander verschiedene
// Materialien an den Magneten, beobachtet, sortiert in zwei Gruppen
// und findet die Regel selbst (nur Eisen, Nickel, Kobalt / Stahl).
// Konfrontiert die Fehlvorstellung "alle Metalle sind magnetisch".
// ═══════════════════════════════════════════════════════

const _MSF_MAT = [
  { k: 'eisen',   name: 'Eisen-Nagel',        ic: '🔩', mag: true,  hint: 'Eisen' },
  { k: 'stahl',   name: 'Büroklammer (Stahl)', ic: '📎', mag: true,  hint: 'Stahl = viel Eisen' },
  { k: 'nickel',  name: 'Nickel-Münze',       ic: '🪙', mag: true,  hint: 'Nickel' },
  { k: 'alu',     name: 'Alu-Dose',           ic: '🥫', mag: false, hint: 'Aluminium (Metall!)' },
  { k: 'kupfer',  name: 'Kupfer-Draht',       ic: '🧵', mag: false, hint: 'Kupfer (Metall!)' },
  { k: 'holz',    name: 'Holz-Stab',          ic: '🪵', mag: false, hint: 'Holz' },
  { k: 'blech1',  name: 'Blech 1',            ic: '🔲', mag: false, hint: 'Aluminium-Blech' },
  { k: 'blech2',  name: 'Blech 2',            ic: '🔳', mag: false, hint: 'Aluminium-Blech' },
  { k: 'blech3',  name: 'Blech 3',            ic: '⬜', mag: true,  hint: 'Stahlblech' }
];
let _msf = null;
// Diagnose-Modus (Lernzyklus): trägt die Schüler-Vermutungen in die Simulation,
// damit direkt am Experiment verglichen werden kann. null = normale Simulation.
let _msfDiag = null;
function _msfSetDiagnose(cfg) { _msfDiag = cfg || null; }

function _msfInit() {
  _msf = { cur: 0, tested: {}, order: [], flash: 0, anim: 0, result: null };
}

function _msfHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim msf-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🧲 Wovon hängt es ab, ob der Magnet an einem Blech hält?</h3>
    <div class="fpm-note" style="margin-top:2px">In die Bude soll ein Blech geschraubt werden – daran sollen später Zettel halten. Halte jeden Gegenstand an den Magneten. Beobachte: Wird er <b>angezogen</b> oder nicht?${_msfDiag ? ' Vergleiche direkt mit deiner <b>Vermutung</b> in der Tabelle!' : ' Sortiere und finde die Regel selbst.'}</div>
    <div class="fpm-grid">
      <div>
        <canvas id="msfAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="fpm-label" style="margin-top:8px">Klicke ein Material an – es wird an den Magneten gehalten:</div>
        <div class="msf-chips" id="msfChips">${_msfChipsHTML()}</div>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn" onclick="_msfReset()">🔄 Alles zurücksetzen</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Beobachtung – deine zwei Gruppen</div>
        <div class="msf-sort">
          <div class="msf-col msf-yes"><div class="msf-col-h">🧲 wird angezogen</div><div id="msfYes"></div></div>
          <div class="msf-col msf-no"><div class="msf-col-h">🚫 wird nicht angezogen</div><div id="msfNo"></div></div>
        </div>
        <div class="fpm-tablewrap" style="margin-top:10px">
          <table class="sim-table">
            <thead>${_msfDiag
              ? '<tr><th>Material</th><th>🔮 deine Vermutung</th><th>🧲 Experiment</th></tr>'
              : '<tr><th>Gegenstand</th><th>Magnet hält? (ja / nein)</th></tr>'}</thead>
            <tbody id="msfTbody"></tbody>
          </table>
          <div class="fpm-empty" id="msfEmpty">Noch nichts getestet.<br>Klicke oben ein Material an.</div>
        </div>
        <div class="msf-regel" id="msfRegel"></div>
        ${_msfDiag ? '<div class="msf-diag-eval" id="msfDiagEval" style="display:none"></div>' : ''}
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Magnetisch sind nur <b>Eisen, Nickel und Kobalt</b> (und Stahl). &nbsp;|&nbsp; Achtung: Nicht jedes Metall ist magnetisch!
    </p>
    ${_msfArbeitsblattHTML()}
  </div>`;
}

function _msfChipsHTML() {
  return _MSF_MAT.map((m, i) => {
    const t = _msf.tested[m.k];
    const cls = t === undefined ? '' : (t ? ' yes' : ' no');
    const mark = t === undefined ? '' : (t ? ' ✓' : ' ✗');
    return `<button class="msf-chip${cls}${i === _msf.cur ? ' cur' : ''}" onclick="_msfTestMat(${i})">${m.ic} ${m.name}${mark}</button>`;
  }).join('');
}

// ── Bedienung ──────────────────────────────────────────
function _msfTestMat(i) {
  _msf.cur = i;
  const m = _MSF_MAT[i];
  if (_msf.tested[m.k] === undefined) _msf.order.push(m.k);
  _msf.tested[m.k] = m.mag;
  _msf.result = m.mag; _msf.anim = 1; _msf.flash = 1;
  _msfRender();
}
function _msfReset() {
  if (_msf.order.length && !confirm('Alle Testergebnisse zurücksetzen?')) return;
  _msf.tested = {}; _msf.order = []; _msf.result = null; _msf.anim = 0;
  _msfRender();
}
function _msfRender() {
  const chips = document.getElementById('msfChips'); if (chips) chips.innerHTML = _msfChipsHTML();
  const yes = document.getElementById('msfYes'), no = document.getElementById('msfNo');
  const mk = arr => arr.map(k => { const m = _MSF_MAT.find(x => x.k === k); return `<span class="msf-tag">${m.ic} ${m.name}</span>`; }).join('') || '<span class="msf-none">– noch leer –</span>';
  if (yes) yes.innerHTML = mk(_msf.order.filter(k => _msf.tested[k]));
  if (no) no.innerHTML = mk(_msf.order.filter(k => !_msf.tested[k]));
  const tb = document.getElementById('msfTbody');
  const empty = document.getElementById('msfEmpty');
  if (empty) empty.style.display = _msf.order.length ? 'none' : 'block';
  if (tb) tb.innerHTML = _msf.order.map(k => {
    const m = _MSF_MAT.find(x => x.k === k);
    if (_msfDiag) {
      const guessed = !!_msfDiag.pred[k];
      const real = !!m.mag;
      const match = guessed === real;
      return `<tr class="${match ? 'msf-diag-match' : 'msf-diag-surprise'}">
        <td>${m.ic} ${m.name}</td>
        <td class="msf-guess">${guessed ? 'angezogen' : 'nicht'}</td>
        <td><b class="${real ? 'msf-ja' : 'msf-nein'}">${real ? 'Ja' : 'Nein'}</b> ${match ? '<span class="msf-ok">✓</span>' : '<span class="msf-sp">💡</span>'}</td></tr>`;
    }
    return `<tr><td>${m.ic} ${m.name}</td><td><b class="${m.mag ? 'msf-ja' : 'msf-nein'}">${m.mag ? 'Ja' : 'Nein'}</b></td></tr>`;
  }).join('');
  const reg = document.getElementById('msfRegel');
  if (reg) {
    if (_msf.order.length >= _MSF_MAT.length) {
      reg.innerHTML = '🎯 <b>Alle getestet!</b> Nur <b>Eisen, Nickel, Kobalt</b> (und Stahl, weil es viel Eisen enthält) werden angezogen. Kupfer und Aluminium sind zwar Metalle, aber <b>nicht</b> magnetisch.';
      reg.style.display = 'block';
    } else { reg.innerHTML = 'Getestet: ' + _msf.order.length + ' von ' + _MSF_MAT.length + '. Teste alle Materialien und finde die Regel!'; reg.style.display = 'block'; }
  }
  // Diagnose-Modus: Auswertung erst freigeben, wenn ALLE Materialien getestet sind
  if (_msfDiag) {
    const evalEl = document.getElementById('msfDiagEval');
    if (evalEl) {
      if (_msf.order.length >= _MSF_MAT.length) {
        let surprises = 0;
        _MSF_MAT.forEach(m => { if ((!!_msfDiag.pred[m.k]) !== !!m.mag) surprises++; });
        const line = surprises === 0
          ? 'Stark – alle deine Vermutungen haben zum Experiment gepasst! 🎯'
          : `Du hattest bei <b>${surprises}</b> ${surprises === 1 ? 'Material' : 'Materialien'} eine <b>Überraschung</b>. Genau deshalb prüft man in der Naturwissenschaft am Experiment.`;
        evalEl.innerHTML = `<div class="msf-diag-done">✅ <b>Alle Materialien getestet!</b><br>${line}</div>
          <button class="sim-btn primary" style="margin-top:8px" onclick="_msfDiagToAuswertung()">🔎 Zur Auswertung →</button>`;
        evalEl.style.display = 'block';
      } else {
        evalEl.innerHTML = `<div class="msf-diag-progress">Noch <b>${_MSF_MAT.length - _msf.order.length}</b> von ${_MSF_MAT.length} Materialien testen – dann kannst du auswerten.</div>`;
        evalEl.style.display = 'block';
      }
    }
  }
}
function _msfDiagToAuswertung() {
  closePhysicsSim();
  if (typeof _diagShowAuswertung === 'function') _diagShowAuswertung();
}

// ── Animation ──────────────────────────────────────────
function _msfUpdate(dt) { if (_msf) { _msf.anim = Math.max(0, _msf.anim - dt * 0.8); _msf.flash = Math.max(0, _msf.flash - dt * 2); } }
function _msfDraw(ctx, cv) {
  if (!_msf) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#f0f9ff'; ctx.fillRect(0, 0, W, H);
  const midY = H / 2 - 6;
  // Stabmagnet links
  const mx = 40, mw = 120, mh = 46;
  ctx.fillStyle = '#dc2626'; ctx.fillRect(mx, midY - mh / 2, mw / 2, mh);
  ctx.fillStyle = '#2563eb'; ctx.fillRect(mx + mw / 2, midY - mh / 2, mw / 2, mh);
  ctx.fillStyle = '#fff'; ctx.font = '700 18px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('N', mx + mw / 4, midY); ctx.fillText('S', mx + 3 * mw / 4, midY);
  ctx.textBaseline = 'alphabetic';
  // aktuelles Material
  const m = _MSF_MAT[_msf.cur];
  const restX = W - 90;
  const nearX = mx + mw + 26;
  const p = 1 - _msf.anim;                 // 0 → 1
  let itemX = restX, shake = 0;
  if (m.mag) itemX = restX - p * (restX - nearX);
  else shake = _msf.anim > 0 ? Math.sin(p * 40) * 4 : 0;
  ctx.font = '34px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText(m.ic, itemX + shake, midY + 12);
  ctx.fillStyle = '#334155'; ctx.font = '700 13px sans-serif';
  ctx.fillText(m.name, W / 2 + 30, 26);
  // Ergebnistext
  if (_msf.tested[m.k] !== undefined) {
    ctx.font = '700 14px sans-serif';
    if (m.mag) { ctx.fillStyle = '#16a34a'; ctx.fillText('→ wird angezogen!', W / 2 + 30, H - 22); }
    else { ctx.fillStyle = '#b45309'; ctx.fillText('bleibt liegen – nicht magnetisch', W / 2 + 30, H - 22); }
  } else {
    ctx.fillStyle = '#94a3b8'; ctx.font = '12px sans-serif';
    ctx.fillText('Klicke ein Material an', W / 2 + 30, H - 22);
  }
  // Anziehungspfeil
  if (m.mag && _msf.anim > 0.02) {
    ctx.strokeStyle = '#16a34a'; ctx.lineWidth = 2; ctx.setLineDash([5, 4]);
    ctx.beginPath(); ctx.moveTo(itemX - 18, midY); ctx.lineTo(nearX + 6, midY); ctx.stroke(); ctx.setLineDash([]);
  }
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.1.1  (ns = 'magstoff') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _msfArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('magstoff')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('magstoff')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Welche Stoffe zieht ein Magnet an – und welche nicht?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        <div class="ab-t">Welche Materialien werden deiner Meinung nach angezogen? Schreibe sie auf.</div>
        ${ta('v1', 'Ich vermute, angezogen werden: …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Klicke oben nacheinander <b>jedes</b> Material an.</li>
          <li>Beobachte genau: Wird es zum Magneten gezogen oder nicht?</li>
          <li>Trage dein Ergebnis in die Tabelle ein (Ja / Nein).</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Eisen-Nagel</td><td>${inp('e_eisen', 'Ja/Nein')}</td><td>Alu-Dose</td><td>${inp('e_alu', 'Ja/Nein')}</td></tr>
          <tr><td>Büroklammer (Stahl)</td><td>${inp('e_stahl', 'Ja/Nein')}</td><td>Kupfer-Draht</td><td>${inp('e_kupfer', 'Ja/Nein')}</td></tr>
          <tr><td>Nickel-Münze</td><td>${inp('e_nickel', 'Ja/Nein')}</td><td>Holz-Stab</td><td>${inp('e_holz', 'Ja/Nein')}</td></tr>
          <tr><td>Plastik-Stein</td><td>${inp('e_plastik', 'Ja/Nein')}</td><td>Glas-Murmel</td><td>${inp('e_glas', 'Ja/Nein')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne den Magneten und einen Eisen-Nagel, der angezogen wird. Zeichne einen Pfeil für die Anziehung.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Kupfer und Aluminium sind <b>Metalle</b> – werden sie angezogen? ${inp('a1', 'Ja/Nein')}</li>
          <li>Was haben die angezogenen Materialien gemeinsam? ${inp('a2', 'sie enthalten …')}</li>
          <li>Stimmt der Satz „Alle Metalle sind magnetisch"? ${inp('a3', 'Ja/Nein, weil …')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Ein Magnet zieht nur ${inp('m1', 'welche 3 Stoffe?')} an.<br>
        Man nennt diese Stoffe <b>magnetisch</b> (Fachwort: ferromagnetisch).<br>
        ${inp('m2', 'Alle / Nicht alle')} Metalle sind magnetisch – Kupfer und Alu zum Beispiel nicht.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Ein Magnet hält an der <b>Kühlschranktür</b>, aber nicht an einer <b>Alu-Getränkedose</b>. Erkläre warum.</div>
        ${ta('tr1', 'Der Magnet hält an der Kühlschranktür, weil … Die Alu-Dose …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="msfMini">${_msfMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_msfSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_msfSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_msfSelf(3)">😃 sicher</button>
          <span id="msfSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="msfSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Angezogen: Eisen-Nagel, Büroklammer (Stahl), Nickel-Münze. Nicht angezogen: Alu-Dose, Kupfer-Draht, Holz, Plastik, Glas.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Ferromagnetisch sind nur Eisen (Fe), Nickel (Ni) und Kobalt (Co) sowie Legierungen wie Stahl (überwiegend Eisen). Magnetismus ist keine allgemeine Metalleigenschaft.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Alle Metalle sind magnetisch" – Gegenbeispiele Kupfer/Alu bewusst einbauen. (2) „Glänzendes/Silbernes ist magnetisch." (3) „Schwere Dinge werden angezogen."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Erst vermuten lassen, dann testen; Kupfer und Alu gezielt als Metalle benennen, die NICHT magnetisch sind; die drei magnetischen Stoffe farbig markieren.</div>
        <div class="ab-t"><b>Musterlösung.</b> 6.1 Nein · 6.2 „sie enthalten Eisen/Nickel" · 6.3 „Nein – Kupfer und Alu sind Metalle, aber nicht magnetisch". Merksatz: Eisen, Nickel, Kobalt · Nicht alle. Transfer: Kühlschranktür ist aus Stahl (Eisen) → magnetisch; Alu ist nicht magnetisch. Minidiagnose: 1→Eisen · 2→„nicht magnetisch" · 3→„nur Eisen, Nickel, Kobalt".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('magstoff')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('magstoff', 'Welche Stoffe zieht ein Magnet an?', body);
}

// ── Minidiagnose ───────────────────────────────────────
const _MSF_MINI = [
  { q: '1. Welches Material zieht ein Magnet an?',
    opts: ['Kupfer', 'Eisen', 'Holz'], correct: 1,
    fb: ['Kupfer ist ein Metall, aber nicht magnetisch. Probiere es in der Simulation.',
         'Richtig! Eisen wird angezogen.',
         'Holz ist nicht magnetisch. Denk an Nägel und Schrauben.'] },
  { q: '2. Ein Magnet hält an einer Stahltür, aber nicht an einer Alu-Dose. Warum?',
    opts: ['Alu ist zu leicht', 'Alu ist nicht magnetisch (kein Eisen/Nickel/Kobalt)', 'Alu ist zu glatt'], correct: 1,
    fb: ['Am Gewicht liegt es nicht. Denk an das Material.',
         'Richtig! Aluminium gehört nicht zu den magnetischen Stoffen.',
         'Die Oberfläche ist egal – es kommt auf das Material an.'] },
  { q: '3. Sind alle Metalle magnetisch?',
    opts: ['Ja, alle Metalle', 'Nein, nur Eisen, Nickel und Kobalt', 'Nur Gold und Silber'], correct: 1,
    fb: ['Kupfer und Alu sind Metalle und trotzdem nicht magnetisch.',
         'Richtig! Nur Eisen, Nickel, Kobalt (und Stahl) sind magnetisch.',
         'Gold und Silber sind gerade nicht magnetisch.'] }
];
function _msfMiniHTML() {
  return _MSF_MINI.map((m, qi) =>
    `<div class="sha-q">
       <div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_msfAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="msfFb${qi}"></div>
     </div>`).join('');
}
function _msfAns(qi, oi) {
  const m = _MSF_MINI[qi];
  const el = document.getElementById('msfFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi];
  el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _msfSelf(n) {
  const out = document.getElementById('msfSelfOut'), val = document.getElementById('msfSelfVal');
  if (val) { val.value = String(n); _abSave('magstoff'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.1.5  WIE ENTSTEHT EIN ELEKTROMAGNET?  (Tragkraft messen)
// Realschule NRW – Klasse 5 · Inhaltsfeld "Strom und Magnetismus"
// Handlungsorientiert: Spule mit Eisenkern + Batterie hebt Büro-
// klammern. Zwei Messreihen (nur eine Größe verändern):
//   • Windungszahl N verändern (I fest) → Tragkraft ~ N
//   • Stromstärke I verändern (N fest)   → Tragkraft ~ I
// Modell: Tragkraft T = k · N · I  (T in Anzahl Büroklammern).
// ═══════════════════════════════════════════════════════

const _ELM_K = 0.03;       // Modellkonstante
const _ELM_I_FIX = 2;      // feste Stromstärke (A), wenn N verändert wird
const _ELM_N_FIX = 150;    // feste Windungszahl, wenn I verändert wird
let _elm = null;

function _elmT(N, I) { return _ELM_K * N * I; }              // wahre Tragkraft
function _elmClips(N, I) { return Math.round(_elmT(N, I)); }  // gemessene (ganze Klammern)

const _ELM_CFG = {
  windungen: { min: 50, max: 300, step: 50, val: 150, lbl: 'Windungszahl N', unit: '', marks: [50, 100, 150, 200, 250, 300] },
  strom:     { min: 1,  max: 5,   step: 1,  val: 2,   lbl: 'Stromstärke I',  unit: 'A', marks: [1, 2, 3, 4, 5] }
};

const _ELM_PRESETS = [
  // Preset 0 – Windungszahl verändern: T über N (Ursprungsgerade)
  { tab: 'Windungen N → Tragkraft', xl: 'Windungszahl N', yl: 'Tragkraft (Büroklammern)',
    x: r => r.mode === 'windungen' ? r.N : NaN, y: r => r.T, grp: r => r.I,
    gl: k => 'Strom fest bei I = ' + _fpmNum(+k, 0) + ' A', slope: k => _ELM_K * (+k),
    col: (k, i) => _MLAB_PALETTE[i % _MLAB_PALETTE.length],
    curveFn: (xv, k) => _ELM_K * (+k) * xv,
    note: 'Ursprungsgerade ⇒ Tragkraft ~ N. Je mehr Windungen, desto stärker der Magnet – doppelt so viele Windungen = doppelte Tragkraft.',
    typ: 'proportionale Funktion (Ursprungsgerade)', form: 'T = k · I · N',
    param: () => 'I fest = ' + _ELM_I_FIX + ' A',
    term: () => (_ELM_K * _ELM_I_FIX).toString() + '*x',
    deutung: 'Mehr Windungen bündeln das Magnetfeld stärker. Die Tragkraft wächst gleichmäßig mit der Windungszahl.',
    ergebnis: (g0) => _mlabErgebnis('Tragkraft pro Windung (Steigung)',
      _fpmNum(g0.fit.k, 3), 'Klammern/Windung', _fpmNum(_ELM_K * (+g0.key), 3), 'T = k·I·N  ⇒  mehr Windungen = stärker') },
  // Preset 1 – Stromstärke verändern: T über I (Ursprungsgerade)
  { tab: 'Strom I → Tragkraft', xl: 'Stromstärke I in A', yl: 'Tragkraft (Büroklammern)',
    x: r => r.mode === 'strom' ? r.I : NaN, y: r => r.T, grp: r => r.N,
    gl: k => 'Windungen fest bei N = ' + _fpmNum(+k, 0), slope: k => _ELM_K * (+k),
    col: (k, i) => _MLAB_PALETTE[(i + 2) % _MLAB_PALETTE.length],
    curveFn: (xv, k) => _ELM_K * (+k) * xv,
    note: 'Ursprungsgerade ⇒ Tragkraft ~ I. Je größer die Stromstärke, desto stärker der Magnet – doppelter Strom = doppelte Tragkraft.',
    typ: 'proportionale Funktion (Ursprungsgerade)', form: 'T = k · N · I',
    param: () => 'N fest = ' + _ELM_N_FIX,
    term: () => (_ELM_K * _ELM_N_FIX).toString() + '*x',
    deutung: 'Mehr Strom bedeutet ein stärkeres Magnetfeld. Die Tragkraft wächst gleichmäßig mit der Stromstärke.',
    ergebnis: (g0) => _mlabErgebnis('Tragkraft pro Ampere (Steigung)',
      _fpmNum(g0.fit.k, 2), 'Klammern/A', _fpmNum(_ELM_K * (+g0.key), 2), 'T = k·N·I  ⇒  mehr Strom = stärker') }
];

function _elmInit() {
  _elm = {
    mode: 'windungen', N: _ELM_N_FIX, I: _ELM_I_FIX, flash: 0, t: 0,
    rows: [], nextId: 1, preset: 0, fn: null, fnAuto: false, origin: true, showTheory: false,
    pre: 'elm', plotId: 'elmPlot', fitId: 'elmFit', fnId: 'elmFn', fnErrId: 'elmErr', theoId: 'elmTheo',
    presets: _ELM_PRESETS
  };
}

function _elmHTML() {
  const c = _ELM_CFG[_elm.mode];
  const varVal = _elm.mode === 'windungen' ? _elm.N : _elm.I;
  return `<div class="sim-box sim-box-wide fpm-sim elm-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🧲⚡ Wie stark ist ein Elektromagnet?</h3>
    <div class="fpm-note" style="margin-top:2px">Eine Spule mit Eisenkern wird zum Magneten, sobald Strom fließt. Sie hebt Büroklammern. <b>Verändere nur eine Größe</b> und miss die Tragkraft.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="elmAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn${_elm.mode === 'windungen' ? ' primary' : ''}" id="elmMode0" onclick="_elmSetMode('windungen')">🌀 Windungszahl ändern</button>
          <button class="sim-btn${_elm.mode === 'strom' ? ' primary' : ''}" id="elmMode1" onclick="_elmSetMode('strom')">⚡ Stromstärke ändern</button>
        </div>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label"><b id="elmVarName">${c.lbl}</b>: <b id="elmVarLbl">${_fpmNum(varVal, 0)}${c.unit ? ' ' + c.unit : ''}</b></span>
          <input type="range" id="elmVar" min="${c.min}" max="${c.max}" step="${c.step}" value="${varVal}"
            oninput="_elmSetVar(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-note" style="margin-top:4px">Tragkraft jetzt: <b id="elmTLbl">${_elmClips(_elm.N, _elm.I)} Büroklammern</b> &nbsp;·&nbsp; nur mit ungefährlicher Batterie-Kleinspannung!</div>
      </div>
      <div>
        <div class="fpm-label">Messung – Wert einstellen, dann Messwert übernehmen</div>
        <div class="sim-btn-row">
          <button class="sim-btn primary" onclick="_elmMessen()">＋ Messwert übernehmen</button>
          <button class="sim-btn" onclick="_elmDemo()">📋 Beispielmessreihe</button>
          <button class="sim-btn" onclick="_elmClear()">🗑 Tabelle leeren</button>
        </div>
        <div class="fpm-tablewrap">
          <table class="sim-table">
            <thead><tr><th>N</th><th>I (A)</th><th>Tragkraft</th><th></th></tr></thead>
            <tbody id="elmTbody"></tbody>
          </table>
          <div class="fpm-empty" id="elmEmpty">Noch keine Messwerte.<br>Wert einstellen → „Messwert übernehmen".</div>
        </div>
      </div>
    </div>
    <div class="fpm-label" style="margin-top:12px">Auswertung – trage die Tragkraft über die veränderte Größe auf</div>
    ${_mlabAuswertungHTML(_elm, { preset: '_elmSetPreset', setfn: '_elmSetFn', theo: '_elmTheorieFn', clear: '_elmClearFn', bool: '_elmSetBool' })}
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>Mehr Windungen → stärker</b> &nbsp;|&nbsp; <b>Mehr Strom → stärker</b> &nbsp;|&nbsp; der Eisenkern verstärkt den Magneten
    </p>
    ${_elmArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _elmSetVar(v) {
  if (_elm.mode === 'windungen') _elm.N = +v; else _elm.I = +v;
  const c = _ELM_CFG[_elm.mode];
  const el = document.getElementById('elmVarLbl'); if (el) el.textContent = _fpmNum(+v, 0) + (c.unit ? ' ' + c.unit : '');
  const tl = document.getElementById('elmTLbl'); if (tl) tl.textContent = _elmClips(_elm.N, _elm.I) + ' Büroklammern';
}
function _elmSwitch(mode, preset) {
  if (mode !== _elm.mode && _elm.rows.length &&
      !confirm('Für eine neue Messreihe wird die Tabelle geleert. Fortfahren?')) {
    for (let k = 0; k < _elm.presets.length; k++)
      document.getElementById('elmTab' + k)?.classList.toggle('on', k === _elm.preset);
    return;
  }
  if (mode !== _elm.mode) { _elm.rows = []; _elmRenderTable(); }
  _elm.mode = mode;
  const c = _ELM_CFG[mode];
  _elm.N = mode === 'windungen' ? c.val : _ELM_N_FIX;
  _elm.I = mode === 'windungen' ? _ELM_I_FIX : c.val;
  document.getElementById('elmMode0')?.classList.toggle('primary', mode === 'windungen');
  document.getElementById('elmMode1')?.classList.toggle('primary', mode === 'strom');
  const sl = document.getElementById('elmVar');
  if (sl) { sl.min = c.min; sl.max = c.max; sl.step = c.step; sl.value = c.val; }
  const nm = document.getElementById('elmVarName'); if (nm) nm.textContent = c.lbl;
  const lb = document.getElementById('elmVarLbl'); if (lb) lb.textContent = _fpmNum(c.val, 0) + (c.unit ? ' ' + c.unit : '');
  const tl = document.getElementById('elmTLbl'); if (tl) tl.textContent = _elmClips(_elm.N, _elm.I) + ' Büroklammern';
  _mlabSetPreset(_elm, preset);
}
function _elmSetMode(m) { _elmSwitch(m, m === 'windungen' ? 0 : 1); }
function _elmMessRow(mode, N, I) {
  const Tt = _elmT(N, I) * (1 + (Math.random() - 0.5) * 0.06);   // Ablese-Streuung
  return { mode, N, I, T: Math.max(0, Math.round(Tt)) };
}
function _elmMessen() { const r = _elmMessRow(_elm.mode, _elm.N, _elm.I); _elmAddRow(r); _elm.flash = 1; }
function _elmDemo() {
  const c = _ELM_CFG[_elm.mode];
  c.marks.forEach(m => {
    const N = _elm.mode === 'windungen' ? m : _ELM_N_FIX;
    const I = _elm.mode === 'windungen' ? _ELM_I_FIX : m;
    const r = _elmMessRow(_elm.mode, N, I);
    _elm.rows.push({ id: _elm.nextId++, mode: r.mode, N: r.N, I: r.I, T: r.T });
  });
  _elmRenderTable(); _mlabDrawPlot('elmPlot', _elm);
}
function _elmAddRow(r) { _elm.rows.push({ id: _elm.nextId++, mode: r.mode, N: r.N, I: r.I, T: r.T }); _elmRenderTable(); _mlabDrawPlot('elmPlot', _elm); }
function _elmDelRow(id) { _elm.rows = _elm.rows.filter(r => r.id !== id); _elmRenderTable(); _mlabDrawPlot('elmPlot', _elm); }
function _elmClear() {
  if (_elm.rows.length && !confirm('Alle ' + _elm.rows.length + ' Messwerte löschen?')) return;
  _elm.rows = []; _elmRenderTable(); _mlabDrawPlot('elmPlot', _elm);
}
function _elmRenderTable() {
  const tb = document.getElementById('elmTbody'); if (!tb) return;
  const empty = document.getElementById('elmEmpty');
  if (empty) empty.style.display = _elm.rows.length ? 'none' : 'block';
  const col = _MLAB_PALETTE[(_elm.mode === 'windungen' ? 0 : 2)];
  tb.innerHTML = _elm.rows.map(r => {
    const varN = r.mode === 'windungen';
    return `<tr>
       <td${varN ? ' class="sha-var"' : ''}>${varN ? '<span class="fpm-dot" style="background:' + col + '"></span>' : ''}${_fpmNum(r.N, 0)}</td>
       <td${!varN ? ' class="sha-var"' : ''}>${!varN ? '<span class="fpm-dot" style="background:' + col + '"></span>' : ''}${_fpmNum(r.I, 0)}</td>
       <td><b>${_fpmNum(r.T, 0)}</b></td>
       <td class="fpm-del" onclick="_elmDelRow(${r.id})" title="löschen">✕</td></tr>`;
  }).join('');
}

// ── Wiring ─────────────────────────────────────────────
function _elmSetPreset(i) { _elmSwitch(i === 0 ? 'windungen' : 'strom', i); }
function _elmSetFn(s) { _mlabSetFn(_elm, s); }
function _elmTheorieFn() { _mlabTheorieFn(_elm); }
function _elmClearFn() { _mlabClearFn(_elm); }
function _elmSetBool(k, v) { _elm[k] = v; _mlabDrawPlot('elmPlot', _elm); }

// ── Animation ──────────────────────────────────────────
function _elmUpdate(dt) { if (_elm) { _elm.t += dt; _elm.flash = Math.max(0, _elm.flash - dt * 1.5); } }
function _elmDraw(ctx, cv) {
  if (!_elm) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#f0f9ff'; ctx.fillRect(0, 0, W, H);
  const cx = 150, coreTop = 30, coreBot = 170, coreW = 26;
  // Eisenkern
  ctx.fillStyle = '#94a3b8'; ctx.fillRect(cx - coreW / 2, coreTop, coreW, coreBot - coreTop);
  ctx.fillStyle = '#64748b'; ctx.font = '700 10px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('Eisenkern', cx, coreBot + 14);
  // Wicklungen (Anzahl ~ N), Farbe/Dicke ~ I
  const loops = Math.max(3, Math.round(_elm.N / 22));
  const iShade = Math.min(1, _elm.I / 5);
  ctx.strokeStyle = `rgba(${180 - Math.round(120 * iShade)},${60},${200},1)`;
  ctx.lineWidth = 2 + iShade * 2;
  for (let k = 0; k < loops; k++) {
    const y = coreTop + 14 + k * ((coreBot - coreTop - 20) / loops);
    ctx.beginPath(); ctx.ellipse(cx, y, coreW / 2 + 8, 5, 0, 0, Math.PI * 2); ctx.stroke();
  }
  ctx.fillStyle = '#7c3aed'; ctx.font = '700 10px sans-serif';
  ctx.fillText(_elm.N + ' Windungen', cx, 20);
  // Batterie + Strom
  ctx.fillStyle = '#1e293b'; ctx.fillRect(cx + 70, 40, 30, 18);
  ctx.fillStyle = '#facc15'; ctx.fillRect(cx + 100, 45, 4, 8);
  ctx.fillStyle = '#334155'; ctx.font = '10px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText('I = ' + _fpmNum(_elm.I, 0) + ' A', cx + 66, 34);
  // Büroklammern hängen am unteren Pol (Anzahl = Tragkraft, Anzeige gedeckelt)
  const clips = _elmClips(_elm.N, _elm.I);
  const show = Math.min(clips, 24);
  ctx.strokeStyle = _elm.flash > 0.3 ? '#f97316' : '#475569'; ctx.lineWidth = 2;
  for (let k = 0; k < show; k++) {
    const col = k % 6, row = Math.floor(k / 6);
    const px = cx - 30 + col * 12, py = coreBot + 4 + row * 16;
    ctx.beginPath();
    ctx.moveTo(px, py); ctx.lineTo(px, py + 11);
    ctx.arc(px + 4, py + 11, 4, Math.PI, 0, false);
    ctx.lineTo(px + 8, py); ctx.stroke();
  }
  ctx.fillStyle = '#7c3aed'; ctx.font = '700 13px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('Tragkraft: ' + clips + ' Büroklammern', W - 130, 40);
  ctx.fillStyle = '#94a3b8'; ctx.font = '10px sans-serif';
  ctx.fillText('(Anzeige bis 24 Stück)', W - 130, 56);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.1.5  (ns = 'elmag') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _elmArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('elmag')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('elmag')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wovon hängt die Stärke eines Elektromagneten ab?</b> Was macht ihn stärker – mehr Windungen oder mehr Strom?</div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, der Elektromagnet wird stärker, wenn …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung (Versuch 1: Windungszahl ändern)</div>
        <ol class="ab-ol">
          <li>Modus <b>„Windungszahl ändern"</b> wählen (Strom bleibt fest bei I = 2 A).</li>
          <li>Stelle N = 50, 100, 150, 200, 250, 300 ein. Übernimm jeweils die Tragkraft.</li>
          <li>Trage in der Auswertung <b>Tragkraft über N</b> auf.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle (Versuch 1)</div>
        <table class="ab-table"><tbody>
          <tr><td>Windungen N</td><td>50</td><td>100</td><td>150</td><td>200</td><td>250</td><td>300</td></tr>
          <tr><td>Tragkraft (Klammern)</td><td>${inp('t1_1', '')}</td><td>${inp('t1_2', '')}</td><td>${inp('t1_3', '')}</td><td>${inp('t1_4', '')}</td><td>${inp('t1_5', '')}</td><td>${inp('t1_6', '')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Durchführung (Versuch 2: Stromstärke ändern)</div>
        <ol class="ab-ol">
          <li>Modus <b>„Stromstärke ändern"</b> (Windungen bleiben fest bei N = 150).</li>
          <li>Stelle I = 1, 2, 3, 4, 5 A ein und übernimm jeweils die Tragkraft.</li>
        </ol>
        <table class="ab-table"><tbody>
          <tr><td>Stromstärke I (A)</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td></tr>
          <tr><td>Tragkraft (Klammern)</td><td>${inp('t2_1', '')}</td><td>${inp('t2_2', '')}</td><td>${inp('t2_3', '')}</td><td>${inp('t2_4', '')}</td><td>${inp('t2_5', '')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">6 · Skizze</div>
        <div class="ab-t">Zeichne die Spule mit Eisenkern und Energiequelle. Zeichne die hängenden Büroklammern.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">7 · Auswertung</div>
        <ol class="ab-ol">
          <li>Wie liegen die Punkte in beiden Diagrammen? ${inp('a1', 'z. B. auf einer Geraden …')}</li>
          <li>Du verdoppelst die Windungszahl (100 → 200). Was passiert mit der Tragkraft? ${inp('a2', '')}</li>
          <li>Was macht den Magneten stärker – mehr Windungen, mehr Strom, oder beides? ${inp('a3', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">8 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Ein Elektromagnet wird stärker, wenn man die Windungszahl ${inp('m1', 'erhöht/senkt')}.<br>
        Er wird auch stärker, wenn die Stromstärke ${inp('m2', 'größer/kleiner')} wird.<br>
        Der ${inp('m3', 'welcher Kern?')} im Inneren verstärkt den Magneten zusätzlich.</div></div>

      <div class="ab-sec"><div class="ab-h">9 · Transfer (Alltag)</div>
        <div class="ab-t">Auf dem Schrottplatz hebt ein <b>Kran mit Elektromagnet</b> ganze Autos. Warum benutzt man dort einen Elektromagneten und keinen normalen Dauermagneten? Nenne einen Vorteil.</div>
        ${ta('tr1', 'Man benutzt einen Elektromagneten, weil …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="elmMini">${_elmMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_elmSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_elmSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_elmSelf(3)">😃 sicher</button>
          <span id="elmSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="elmSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Messwerte.</b> Versuch 1 (I = 2 A): N = 50/100/150/200/250/300 → ≈ 3/6/9/12/15/18 Klammern (Ursprungsgerade). Versuch 2 (N = 150): I = 1..5 A → ≈ 5/9/14/18/23 Klammern (Ursprungsgerade). Kleine Messstreuung ist normal.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Modell T = k·N·I: Tragkraft proportional zur Windungszahl UND zur Stromstärke. Der weichmagnetische Eisenkern verstärkt das Feld deutlich (Verzicht auf Formel B = µ₀·µ_r·n·I in Kl. 5).</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Die Batteriegröße allein zählt." (2) „Ein Elektromagnet ist immer magnetisch" – nein, nur bei Stromfluss. (3) „Der Eisenkern ist unwichtig."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Streng nur eine Größe verändern; Tragkraft = Anzahl Klammern zählen lassen; Diagramm mit Ausgleichsgerade anlegen.</div>
        <div class="ab-t"><b>Musterlösung.</b> 7.2 „verdoppelt sich" · 7.3 „beides". Merksatz: erhöht · größer · Eisenkern. Transfer: an-/abschaltbar (Strom aus → Last fällt gezielt), Stärke regelbar. Minidiagnose: 1→„nur wenn Strom fließt" · 2→„doppelt so stark" · 3→„Eisenkern".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('elmag')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('elmag', 'Wie stark ist ein Elektromagnet?', body);
}

// ── Minidiagnose ───────────────────────────────────────
const _ELM_MINI = [
  { q: '1. Wann ist die Spule mit Eisenkern magnetisch?',
    opts: ['Immer', 'Nur wenn Strom fließt', 'Nur nachts'], correct: 1,
    fb: ['Ohne Strom ist die Spule kein Magnet. Schalte den Strom in Gedanken aus.',
         'Richtig! Nur bei Stromfluss entsteht das Magnetfeld – das ist der Vorteil.',
         'Mit der Uhrzeit hat es nichts zu tun 🙂'] },
  { q: '2. Du verdoppelst die Windungszahl von 100 auf 200. Was passiert mit der Tragkraft?',
    opts: ['Sie halbiert sich', 'Sie bleibt gleich', 'Sie verdoppelt sich'], correct: 2,
    fb: ['Mehr Windungen machen den Magneten stärker, nicht schwächer.',
         'Schau ins Diagramm – die Gerade steigt an.',
         'Richtig! Doppelte Windungszahl → doppelte Tragkraft (Ursprungsgerade).'] },
  { q: '3. Was verstärkt den Elektromagneten zusätzlich?',
    opts: ['Ein Kupferkern', 'Ein Eisenkern', 'Ein Holzstab'], correct: 1,
    fb: ['Kupfer ist nicht magnetisch – es verstärkt nichts.',
         'Richtig! Der Eisenkern bündelt und verstärkt das Magnetfeld.',
         'Holz hat keine Wirkung auf den Magneten.'] }
];
function _elmMiniHTML() {
  return _ELM_MINI.map((m, qi) =>
    `<div class="sha-q">
       <div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_elmAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="elmFb${qi}"></div>
     </div>`).join('');
}
function _elmAns(qi, oi) {
  const m = _ELM_MINI[qi];
  const el = document.getElementById('elmFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi];
  el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _elmSelf(n) {
  const out = document.getElementById('elmSelfOut'), val = document.getElementById('elmSelfVal');
  if (val) { val.value = String(n); _abSave('elmag'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.1.2  WIE WIRKEN MAGNETPOLE AUFEINANDER?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Strom und Magnetismus"
// Handlungsorientiert: zwei Stabmagnete. Umschalten zwischen
// gleichen Polen (Abstoßung) und ungleichen Polen (Anziehung).
// Abstand verändern → Kraftmesser messen → Kraft ~ 1/d² (fallende
// Kurve): je kleiner der Abstand, desto größer die Kraft.
// ═══════════════════════════════════════════════════════

const _MPO_C = 60;         // Modellkonstante: F = C / d²
let _mpo = null;

function _mpoF(d) { return _MPO_C / (d * d); }

const _MPO_PRESETS = [
  { tab: 'Abstand d → Kraft F', xl: 'Abstand d in cm', yl: 'Kraft F (Skalenteile)',
    x: r => r.d, y: r => r.F, grp: r => 0,
    gl: () => 'Kraftmessung', curve: true,
    col: () => _MLAB_PALETTE[4],
    curveFn: (xv) => _MPO_C / (xv * xv),
    note: 'Keine Gerade, sondern eine fallende Kurve: F ~ 1/d². Je kleiner der Abstand d, desto größer die Kraft. Ganz nah beieinander ziehen (oder stoßen) sich die Magnete sehr stark.',
    typ: 'fallende Kurve (je näher, desto stärker)', form: 'F wird größer, wenn d kleiner wird',
    param: () => 'Kraftmesser in Skalenteilen',
    term: () => _MPO_C.toString() + '/(x*x)',
    deutung: 'Die Kraft zwischen zwei Magneten nimmt mit größerem Abstand schnell ab – und bei kleinem Abstand stark zu.' }
];

function _mpoInit() {
  _mpo = {
    orient: 'anz', d: 5, flash: 0,
    rows: [], nextId: 1, preset: 0, fn: null, fnAuto: false, origin: false, showTheory: false,
    pre: 'mpo', plotId: 'mpoPlot', fitId: 'mpoFit', fnId: 'mpoFn', fnErrId: 'mpoErr', theoId: 'mpoTheo',
    presets: _MPO_PRESETS, marks: [2, 3, 4, 5, 6, 8, 10]
  };
}

function _mpoHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim mpo-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🚪 Wovon hängt es ab, ob die Tür zuhält?</h3>
    <div class="fpm-note" style="margin-top:2px">An der Tür der Bude sitzt ein Magnet, ein zweiter am Rahmen. Drehe einen der beiden Magnete um und beobachte, ob die Tür zugezogen oder wieder aufgedrückt wird.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="mpoAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn${_mpo.orient === 'anz' ? ' primary' : ''}" id="mpoO0" onclick="_mpoSetOrient('anz')">🚪 Magnet an der Tür so herum</button>
          <button class="sim-btn${_mpo.orient === 'abst' ? ' primary' : ''}" id="mpoO1" onclick="_mpoSetOrient('abst')">🔄 Magnet an der Tür umgedreht</button>
        </div>
        <div class="phys-ctrl" style="margin-top:8px">
          <span class="phys-ctrl-label">Abstand d: <b id="mpoDLbl">5 cm</b></span>
          <input type="range" id="mpoVar" min="2" max="12" step="1" value="5"
            oninput="_mpoSetD(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="fpm-note" style="margin-top:4px">Kraftmesser zeigt: <b id="mpoFLbl">${_fpmNum(_mpoF(5), 1)} Skalenteile</b> &nbsp;·&nbsp; <b id="mpoWirk">Anziehung</b></div>
      </div>
      <div>
        <div class="fpm-label">Messung – Abstand einstellen, dann Messwert übernehmen</div>
        <div class="sim-btn-row">
          <button class="sim-btn primary" onclick="_mpoMessen()">＋ Messwert übernehmen</button>
          <button class="sim-btn" onclick="_mpoDemo()">📋 Beispielmessreihe</button>
          <button class="sim-btn" onclick="_mpoClear()">🗑 Tabelle leeren</button>
        </div>
        <div class="fpm-tablewrap">
          <table class="sim-table">
            <thead><tr><th>Abstand d (cm)</th><th>Kraft F</th><th></th></tr></thead>
            <tbody id="mpoTbody"></tbody>
          </table>
          <div class="fpm-empty" id="mpoEmpty">Noch keine Messwerte.<br>Abstand einstellen → „Messwert übernehmen".</div>
        </div>
      </div>
    </div>
    <div class="fpm-label" style="margin-top:12px">Auswertung – trage die Kraft F über den Abstand d auf</div>
    ${_mlabAuswertungHTML(_mpo, { preset: '_mpoSetPreset', setfn: '_mpoSetFn', theo: '_mpoTheorieFn', clear: '_mpoClearFn', bool: '_mpoSetBool' })}
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>Gleiche Pole stoßen sich ab, ungleiche ziehen sich an.</b> &nbsp;|&nbsp; Je kleiner der Abstand, desto größer die Kraft.
    </p>
    ${_mpoArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _mpoSetD(v) {
  _mpo.d = +v;
  const el = document.getElementById('mpoDLbl'); if (el) el.textContent = _fpmNum(+v, 0) + ' cm';
  const fl = document.getElementById('mpoFLbl'); if (fl) fl.textContent = _fpmNum(_mpoF(+v), 1) + ' Skalenteile';
}
function _mpoSetOrient(o) {
  _mpo.orient = o;
  document.getElementById('mpoO0')?.classList.toggle('primary', o === 'anz');
  document.getElementById('mpoO1')?.classList.toggle('primary', o === 'abst');
  const w = document.getElementById('mpoWirk'); if (w) w.textContent = o === 'anz' ? 'Anziehung' : 'Abstoßung';
  _mpo.flash = 1;
}
function _mpoMessRow(d) {
  const Ft = _mpoF(d) * (1 + (Math.random() - 0.5) * 0.04);
  return { d, F: Math.round(Ft * 10) / 10 };
}
function _mpoMessen() { const r = _mpoMessRow(_mpo.d); _mpoAddRow(r); _mpo.flash = 1; }
function _mpoDemo() {
  _mpo.marks.forEach(d => { const r = _mpoMessRow(d); _mpo.rows.push({ id: _mpo.nextId++, d: r.d, F: r.F }); });
  _mpoRenderTable(); _mlabDrawPlot('mpoPlot', _mpo);
}
function _mpoAddRow(r) { _mpo.rows.push({ id: _mpo.nextId++, d: r.d, F: r.F }); _mpoRenderTable(); _mlabDrawPlot('mpoPlot', _mpo); }
function _mpoDelRow(id) { _mpo.rows = _mpo.rows.filter(r => r.id !== id); _mpoRenderTable(); _mlabDrawPlot('mpoPlot', _mpo); }
function _mpoClear() {
  if (_mpo.rows.length && !confirm('Alle ' + _mpo.rows.length + ' Messwerte löschen?')) return;
  _mpo.rows = []; _mpoRenderTable(); _mlabDrawPlot('mpoPlot', _mpo);
}
function _mpoRenderTable() {
  const tb = document.getElementById('mpoTbody'); if (!tb) return;
  const empty = document.getElementById('mpoEmpty');
  if (empty) empty.style.display = _mpo.rows.length ? 'none' : 'block';
  tb.innerHTML = _mpo.rows.map(r =>
    `<tr><td><span class="fpm-dot" style="background:${_MLAB_PALETTE[4]}"></span>${_fpmNum(r.d, 0)}</td>
       <td><b>${_fpmNum(r.F, 1)}</b></td>
       <td class="fpm-del" onclick="_mpoDelRow(${r.id})" title="löschen">✕</td></tr>`).join('');
}

// ── Wiring ─────────────────────────────────────────────
function _mpoSetPreset(i) { _mlabSetPreset(_mpo, i); }
function _mpoSetFn(s) { _mlabSetFn(_mpo, s); }
function _mpoTheorieFn() { _mlabTheorieFn(_mpo); }
function _mpoClearFn() { _mlabClearFn(_mpo); }
function _mpoSetBool(k, v) { _mpo[k] = v; _mlabDrawPlot('mpoPlot', _mpo); }

// ── Animation ──────────────────────────────────────────
function _mpoUpdate(dt) { if (_mpo) _mpo.flash = Math.max(0, _mpo.flash - dt * 1.2); }
function _mpoBar(ctx, x, y, w, h, leftLabel, leftCol, rightCol) {
  ctx.fillStyle = leftCol; ctx.fillRect(x, y, w / 2, h);
  ctx.fillStyle = rightCol; ctx.fillRect(x + w / 2, y, w / 2, h);
  ctx.fillStyle = '#fff'; ctx.font = '700 15px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(leftLabel, x + w / 4, y + h / 2);
  ctx.fillText(leftLabel === 'N' ? 'S' : 'N', x + 3 * w / 4, y + h / 2);
  ctx.textBaseline = 'alphabetic';
}
function _mpoDraw(ctx, cv) {
  if (!_mpo) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#f0f9ff'; ctx.fillRect(0, 0, W, H);
  const midY = H / 2 + 4, mw = 96, mh = 40;
  const anz = _mpo.orient === 'anz';
  // linker Magnet fest: N | S  (S zeigt nach rechts)
  const lx = 60;
  _mpoBar(ctx, lx, midY - mh / 2, mw, mh, 'N', '#dc2626', '#2563eb');
  // rechter Magnet: Abstand skaliert
  const gap = 20 + _mpo.d * 12;
  const rx = lx + mw + gap;
  // Anziehung: linke Seite des rechten Magneten = N (ungleich zu S) → N|S
  // Abstoßung: linke Seite = S (gleich wie S) → S|N
  if (anz) _mpoBar(ctx, rx, midY - mh / 2, mw, mh, 'N', '#dc2626', '#2563eb');
  else _mpoBar(ctx, rx, midY - mh / 2, mw, mh, 'S', '#2563eb', '#dc2626');
  // Kraftpfeile
  const F = _mpoF(_mpo.d), aLen = Math.min(34, 8 + F * 1.6);
  ctx.strokeStyle = _mpo.flash > 0.3 ? '#f97316' : '#16a34a'; ctx.fillStyle = ctx.strokeStyle; ctx.lineWidth = 3;
  const arrY = midY - mh / 2 - 14;
  const drawArrow = (x, dir) => {
    ctx.beginPath(); ctx.moveTo(x, arrY); ctx.lineTo(x + dir * aLen, arrY); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x + dir * aLen, arrY); ctx.lineTo(x + dir * aLen - dir * 6, arrY - 4); ctx.lineTo(x + dir * aLen - dir * 6, arrY + 4); ctx.closePath(); ctx.fill();
  };
  if (anz) { drawArrow(lx + mw, 1); drawArrow(rx, -1); }      // zueinander
  else { drawArrow(lx + mw, -1); drawArrow(rx, 1); }          // voneinander weg
  // Abstandslinie
  ctx.strokeStyle = '#64748b'; ctx.lineWidth = 1; ctx.setLineDash([3, 3]);
  ctx.beginPath(); ctx.moveTo(lx + mw, midY + mh / 2 + 12); ctx.lineTo(rx, midY + mh / 2 + 12); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = '#334155'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('d = ' + _fpmNum(_mpo.d, 0) + ' cm', (lx + mw + rx) / 2, midY + mh / 2 + 26);
  // Kraftmesser oben
  ctx.fillStyle = '#334155'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText((anz ? '↔ Anziehung' : '⇄ Abstoßung') + '  ·  Kraft F = ' + _fpmNum(F, 1), 20, 22);
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(20, 28, 180, 8);
  ctx.fillStyle = '#7c3aed'; ctx.fillRect(20, 28, Math.min(180, F * 12), 8);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.1.2  (ns = 'magpole') – im 0123-Gate
