function _sctArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('schatten3')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('schatten3')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wie und wo entsteht ein Schatten?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, ein Schatten entsteht, wenn … Er liegt …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Entferne den Gegenstand. Gibt es einen Schatten?</li>
          <li>Setze den Gegenstand wieder ein. Wo liegt der Schatten – zur Lampe hin oder von ihr weg?</li>
          <li>Bewege die Lampe nach oben und unten. Wohin wandert der Schatten?</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtung</div>
        <ol class="ab-ol">
          <li>Ohne Gegenstand: Schatten? ${inp('b1', 'ja/nein')}</li>
          <li>Der Schatten liegt der Lampe … ${inp('b2', 'zugewandt/gegenüber')}</li>
          <li>Lampe nach oben → Schatten wandert nach … ${inp('b3', 'oben/unten')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne Lampe, Gegenstand und Schirm. Zeichne die zwei Randstrahlen und den Schatten ein.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Warum entsteht überhaupt ein Schatten? ${inp('a1', 'weil das Licht … und der Körper …')}</li>
          <li>Welche Form hat der Schatten im Vergleich zum Gegenstand? ${inp('a2', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Ein Schatten entsteht, weil Licht ${inp('m1', 'wie?')} verläuft und ein ${inp('m2', 'was für ein?')} Körper es blockiert.<br>
        Der Schatten liegt immer der Lichtquelle ${inp('m3', 'zugewandt/gegenüber')}.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Am Morgen ist dein Schatten lang und zeigt nach Westen, am Abend nach Osten. Erkläre mithilfe der wandernden Sonne, warum sich dein Schatten im Lauf des Tages bewegt.</div>
        ${ta('tr1', 'Mein Schatten wandert, weil die Sonne …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="sctMini">${_sctMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_sctSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_sctSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_sctSelf(3)">😃 sicher</button>
          <span id="sctSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="sctSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Ohne Gegenstand kein Schatten. Mit Gegenstand: Schatten hinter dem Körper, der Lampe gegenüber. Lampe nach oben → Schatten nach unten (und umgekehrt). Schattenform = Umriss des Körpers.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Schatten entsteht durch geradlinige Lichtausbreitung + undurchsichtigen Körper. Bei einer Punktlichtquelle entsteht ein scharf begrenzter Kernschatten; der Schattenraum ist der Bereich hinter dem Körper, das Schattenbild seine Abbildung auf dem Schirm.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Der Schatten klebt am Gegenstand fest." (2) „Der Schatten liegt zur Lampe hin." (3) „Ohne Bewegung des Körpers ändert sich der Schatten nie."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Randstrahlen mit dem Lineal ziehen; Lampe langsam bewegen und Schatten verfolgen; Bezug zur geradlinigen Ausbreitung (5.3.2).</div>
        <div class="ab-t"><b>Musterlösung.</b> 4.1 „nein" · 4.2 „gegenüber" · 4.3 „unten". 6.1 „Licht geradlinig, Körper blockiert" · 6.2 „gleicher Umriss". Merksatz: geradlinig · undurchsichtigen · gegenüber. Transfer: Die Sonne wandert über den Himmel, deshalb ändert sich die Richtung des Schattens. Minidiagnose: 1→„Licht wird blockiert" · 2→„gegenüber der Lampe" · 3→„nach unten".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('schatten3')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('schatten3', 'Wie entsteht ein Schatten?', body);
}

const _SCT_MINI = [
  { q: '1. Warum entsteht ein Schatten?',
    opts: ['Weil Licht um die Ecke geht', 'Weil ein Körper das geradlinige Licht blockiert', 'Weil es dunkel ist'], correct: 1,
    fb: ['Licht geht nicht um die Ecke.',
         'Richtig! Der undurchsichtige Körper blockiert das geradlinige Licht.',
         'Der Schatten entsteht durch das Blockieren, nicht durch Dunkelheit allein.'] },
  { q: '2. Auf welcher Seite des Gegenstands liegt der Schatten?',
    opts: ['Auf der Seite zur Lampe hin', 'Auf der Seite von der Lampe weg', 'Rundherum'], correct: 1,
    fb: ['Zur Lampe hin ist es hell.',
         'Richtig! Der Schatten liegt der Lampe gegenüber.',
         'Nur auf der lichtabgewandten Seite.'] },
  { q: '3. Du schiebst die Lampe nach oben. Wohin wandert der Schatten?',
    opts: ['Nach oben', 'Nach unten', 'Er bleibt gleich'], correct: 1,
    fb: ['Andersherum – der Schatten liegt gegenüber.',
         'Richtig! Lampe nach oben → Schatten nach unten.',
         'Er bewegt sich sehr wohl.'] }
];
function _sctMiniHTML() {
  return _SCT_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_sctAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="sctFb${qi}"></div></div>`).join('');
}
function _sctAns(qi, oi) {
  const m = _SCT_MINI[qi], el = document.getElementById('sctFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _sctSelf(n) {
  const out = document.getElementById('sctSelfOut'), val = document.getElementById('sctSelfVal');
  if (val) { val.value = String(n); _abSave('schatten3'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 5.3.5  WIE ENTSTEHEN KERN- UND HALBSCHATTEN?
// Realschule NRW – Klasse 5 · Inhaltsfeld "Licht und Schall"
// Handlungsorientiert: Größe der Lichtquelle verändern. Punktquelle
// → nur scharfer Kernschatten. Ausgedehnte Quelle → Kernschatten
// (kein Licht) + Halbschatten (nur Teillicht) mit weichem Rand.
// ═══════════════════════════════════════════════════════

let _khs = null;
function _khsInit() { _khs = { s: 0, t: 0 }; }   // s = halbe Höhe der Lichtquelle

function _khsHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim khs-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🌗 Wovon haengt es ab, ob ein Schatten tiefschwarz oder blassgrau ist?</h3>
    <div class="fpm-note" style="margin-top:2px">Auf der Holzkiste stehen Taschenlampen. Eine einzelne Lampe leuchtet fast punktfoermig, zwei nebeneinander wirken wie eine breite Lichtquelle. Veraendere die <b>Breite der Lichtquelle</b> und vergleiche Mitte und Rand des Schattens an der Bretterwand.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="khsAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn" onclick="_khsPreset(0)">🔦 nur eine Taschenlampe</button>
          <button class="sim-btn" onclick="_khsPreset(32)">🔦🔦 zwei Lampen weit auseinander</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Größe der Lichtquelle</div>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Quelle: <b id="khsSLbl">punktförmig</b></span>
          <input type="range" id="khsS" min="0" max="40" step="2" value="0"
            oninput="_khsSetS(this.value)" style="width:100%;accent-color:#7c3aed">
        </div>
        <div class="lmp-status" id="khsStatus"></div>
        <div class="fpm-note" style="margin-top:10px">Schau dir Mitte und Rand des Schattens getrennt an. Trage in die Tabelle im Forscherheft ein, ob die Stelle tiefschwarz oder blassgrau ist.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Punktquelle → nur scharfer <b>Kernschatten</b>. &nbsp;|&nbsp; Ausgedehnte Quelle → <b>Kern-</b> und <b>Halbschatten</b> mit weichem Rand.
    </p>
    ${_khsArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _khsSetS(v) {
  _khs.s = +v;
  const el = document.getElementById('khsSLbl'); if (el) el.textContent = +v < 4 ? 'punktförmig' : (+v < 22 ? 'klein ausgedehnt' : 'groß ausgedehnt');
  _khsStatus();
}
function _khsPreset(v) { _khs.s = v; const sl = document.getElementById('khsS'); if (sl) sl.value = v; _khsSetS(v); }
function _khsStatus() {
  const el = document.getElementById('khsStatus'); if (!el) return;
  if (_khs.s < 4) { el.textContent = '✓ Punktquelle → nur ein scharfer Kernschatten (kein Halbschatten).'; el.className = 'lmp-status on'; }
  else { el.textContent = '✓ Ausgedehnte Quelle → in der Mitte Kernschatten, am Rand ein weicher Halbschatten.'; el.className = 'lmp-status on'; }
}

// ── Animation ──────────────────────────────────────────
function _khsUpdate(dt) { if (_khs) _khs.t += dt; }
function _khsDraw(ctx, cv) {
  if (!_khs) return;
  const W = cv.width, H = cv.height, cy = H / 2;
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#fef9c3'; ctx.fillRect(0, 0, W, H);
  const x0 = 55, xO = W / 2 + 6, hO = 30, xS = W - 40, s = _khs.s;
  const ratio = (xS - x0) / (xO - x0);
  const yTopO = cy - hO, yBotO = cy + hO, yST = cy - s, ySB = cy + s;
  const yPenTop = yST + (yTopO - yST) * ratio;
  const yPenBot = ySB + (yBotO - ySB) * ratio;
  const yUmbTop = ySB + (yTopO - ySB) * ratio;
  const yUmbBot = yST + (yBotO - yST) * ratio;
  // Schirm
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(xS, 16, 8, H - 32);
  // Halbschatten-Band (volle Schattenbreite - sichtbar bleibt davon der graue Saum)
  ctx.fillStyle = 'rgba(71,85,105,0.4)'; ctx.fillRect(xS, yUmbTop, 8, yUmbBot - yUmbTop);
  // Kernschatten-Band (falls vorhanden) - innen, dunkel darueber
  const hasUmbra = yPenTop <= yPenBot;
  if (hasUmbra) { ctx.fillStyle = '#1e293b'; ctx.fillRect(xS, yPenTop, 8, yPenBot - yPenTop); }
  // Randstrahlen
  ctx.strokeStyle = 'rgba(245,158,11,0.55)'; ctx.lineWidth = 1.2; ctx.setLineDash([5, 4]); ctx.lineDashOffset = -(_khs.t * 35) % 9;
  ctx.beginPath();
  ctx.moveTo(x0, yST); ctx.lineTo(xS, yPenTop);
  ctx.moveTo(x0, ySB); ctx.lineTo(xS, yPenBot);
  ctx.moveTo(x0, ySB); ctx.lineTo(xS, yUmbTop);
  ctx.moveTo(x0, yST); ctx.lineTo(xS, yUmbBot);
  ctx.stroke(); ctx.setLineDash([]); ctx.lineDashOffset = 0;
  // Gegenstand
  ctx.fillStyle = '#7c3aed'; ctx.fillRect(xO - 6, yTopO, 12, yBotO - yTopO);
  ctx.fillStyle = '#334155'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Gegenstand', xO, yTopO - 8);
  // Lichtquelle
  ctx.fillStyle = '#f59e0b';
  if (s < 4) { ctx.beginPath(); ctx.arc(x0, cy, 9, 0, 2 * Math.PI); ctx.fill(); }
  else { ctx.fillStyle = 'rgba(250,204,21,0.6)'; ctx.fillRect(x0 - 8, yST, 16, ySB - yST); ctx.fillStyle = '#f59e0b'; ctx.fillRect(x0 - 5, yST, 10, ySB - yST); }
  ctx.fillStyle = '#92400e'; ctx.font = '10px sans-serif'; ctx.fillText(s < 4 ? 'Punktquelle' : 'Lichtquelle', x0, cy - Math.max(s, 9) - 8);
  // Beschriftung der Bänder
  ctx.textAlign = 'left'; ctx.font = '700 10px sans-serif';
  if (hasUmbra) { ctx.fillStyle = '#1e293b'; ctx.fillText('Kernschatten', xS + 12, (yPenTop + yPenBot) / 2); }
  if (s >= 4) { ctx.fillStyle = '#475569'; ctx.fillText('Halbschatten', xS + 12, yUmbTop + 6); }
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 5.3.5  (ns = 'kernschatten') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _khsArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('kernschatten')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('kernschatten')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Warum ist der Rand mancher Schatten scharf und der Rand anderer Schatten weich (verschwommen)?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, der Schattenrand wird weich, wenn …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Stelle die <b>Punktlichtquelle</b> ein. Wie sieht der Schattenrand aus?</li>
          <li>Vergrößere die Lichtquelle Schritt für Schritt. Was erscheint am Rand?</li>
          <li>Stelle die <b>ausgedehnte Quelle</b> ein und finde Kern- und Halbschatten.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtung</div>
        <ol class="ab-ol">
          <li>Punktquelle: Schattenrand ${inp('b1', 'scharf/weich')}, Halbschatten? ${inp('b2', 'ja/nein')}</li>
          <li>Ausgedehnte Quelle: Halbschatten? ${inp('b3', 'ja/nein')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne eine ausgedehnte Lichtquelle, den Gegenstand und auf dem Schirm Kern- und Halbschatten.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Was ist der Unterschied zwischen Kern- und Halbschatten? ${inp('a1', 'Kern = … , Halb = …')}</li>
          <li>Welche Quelle braucht man, damit ein Halbschatten entsteht? ${inp('a2', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Im <b>Kernschatten</b> kommt von der Lichtquelle ${inp('m1', 'wie viel Licht?')} an.<br>
        Im <b>Halbschatten</b> kommt Licht von ${inp('m2', 'einem Teil / der ganzen')} Quelle an.<br>
        Ein Halbschatten entsteht nur bei einer ${inp('m3', 'punktförmigen/ausgedehnten')} Lichtquelle.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Bei einer Sonnenfinsternis gibt es Orte, an denen die Sonne ganz verschwindet (Kernschatten), und Orte, an denen sie nur teilweise verdeckt ist (Halbschatten). Erkläre das mit deinem Wissen.</div>
        ${ta('tr1', 'Bei der Sonnenfinsternis …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="khsMini">${_khsMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_khsSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_khsSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_khsSelf(3)">😃 sicher</button>
          <span id="khsSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="khsSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Punktquelle → scharfer Rand, nur Kernschatten. Ausgedehnte Quelle → in der Mitte Kernschatten (ganz dunkel), außen ein weicher Halbschatten; je größer die Quelle, desto breiter der Halbschatten und desto kleiner der Kernschatten.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Kernschatten: kein Punkt der Quelle „sieht" den Schirmpunkt. Halbschatten: nur ein Teil der Quelle beleuchtet den Punkt. Nur ausgedehnte (oder mehrere) Lichtquellen erzeugen Halbschatten.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Der Halbschatten ist halb so groß." (2) „Auch eine Punktquelle macht Halbschatten." (3) „Kern- und Halbschatten sind gleich dunkel."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Randstrahlen von den Quellenrändern über die Gegenstandskanten ziehen; mit zwei Lampen als einfachem Modell einer ausgedehnten Quelle beginnen.</div>
        <div class="ab-t"><b>Musterlösung.</b> 4.1 „scharf / nein" · 4.3 „ja". 6.1 „Kern = kein Licht, Halb = Teillicht" · 6.2 „ausgedehnte Quelle". Merksatz: kein · einem Teil · ausgedehnten. Transfer: Der Mond wirft Kern- und Halbschatten auf die Erde, weil die Sonne eine ausgedehnte Lichtquelle ist. Minidiagnose: 1→„kein Licht" · 2→„ausgedehnte Quelle" · 3→„Teillicht".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('kernschatten')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('kernschatten', 'Wie entstehen Kern- und Halbschatten?', body);
}

const _KHS_MINI = [
  { q: '1. Wie viel Licht kommt im Kernschatten an?',
    opts: ['Das ganze Licht', 'Gar kein Licht', 'Nur die Hälfte'], correct: 1,
    fb: ['Dann wäre es kein Schatten.',
         'Richtig! Im Kernschatten kommt von der Quelle gar kein Licht an.',
         'Das gilt für den Halbschatten.'] },
  { q: '2. Welche Lichtquelle braucht man, damit ein Halbschatten entsteht?',
    opts: ['Eine Punktquelle', 'Eine ausgedehnte (oder mehrere) Quelle(n)', 'Gar keine'], correct: 1,
    fb: ['Eine Punktquelle macht nur einen scharfen Kernschatten.',
         'Richtig! Nur ausgedehnte Quellen erzeugen einen Halbschatten.',
         'Ohne Licht gibt es gar keinen Schatten.'] },
  { q: '3. Was ist der Halbschatten?',
    opts: ['Ein Bereich mit Teillicht', 'Ein völlig dunkler Bereich', 'Der hellste Bereich'], correct: 0,
    fb: ['Richtig! Im Halbschatten kommt Licht von einem Teil der Quelle an.',
         'Völlig dunkel ist der Kernschatten.',
         'Der Halbschatten ist teilweise beleuchtet, nicht der hellste.'] }
];
function _khsMiniHTML() {
  return _KHS_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_khsAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="khsFb${qi}"></div></div>`).join('');
}
function _khsAns(qi, oi) {
  const m = _KHS_MINI[qi], el = document.getElementById('khsFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _khsSelf(n) {
  const out = document.getElementById('khsSelfOut'), val = document.getElementById('khsSelfVal');
  if (val) { val.value = String(n); _abSave('kernschatten'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 6.1.1  SIND TEMPERATUR UND WÄRME DAS GLEICHE?
// Realschule NRW – Klasse 6 · Inhaltsfeld "Sonnenenergie und Wärme"
// Handlungsorientiert: zwei Gefäße mit Wasser (Menge + Temperatur
// einstellbar). Temperatur (°C) sagt, wie warm; die Wärmemenge
// (Energie) hängt von Menge UND Temperatur ab. In Kontakt bringen:
// Wärme fließt vom warmen zum kalten Wasser bis zur Mischtemperatur.
// ═══════════════════════════════════════════════════════

let _tw = null;
function _twInit() { _tw = { m1: 1, T1: 80, m2: 2, T2: 20, mixed: false, a1: 80, a2: 20, t: 0 }; }
function _twWaerme(m, T) { return m * T; }                       // relative Wärmemenge (Einheiten)
function _twMix() { return (_tw.m1 * _tw.T1 + _tw.m2 * _tw.T2) / (_tw.m1 + _tw.m2); }

function _twHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim tw-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🌡️ Wovon hängt es ab, ob ein kalter Gegenstand von allein warm wird?</h3>
    <div class="fpm-note" style="margin-top:2px">Ein kalter Metalllöffel steht im heißen Tee. Links die Tasse, rechts das zweite Gefäß. Stelle für beide Menge und Temperatur ein und bring sie dann in Kontakt. Beobachte, was mit beiden Temperaturen passiert.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="twAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn primary" onclick="_twContact()">🔗 In Kontakt bringen</button>
          <button class="sim-btn" onclick="_twReset()">🔄 Zurücksetzen</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Gefäß 1 (links)</div>
        <div class="phys-ctrl"><span class="phys-ctrl-label">Menge: <b id="twM1L">1 L</b></span>
          <input type="range" id="twM1" min="0.5" max="3" step="0.5" value="1" oninput="_twSet('m1',this.value)" style="width:100%;accent-color:#7c3aed"></div>
        <div class="phys-ctrl" style="margin-top:4px"><span class="phys-ctrl-label">Temperatur: <b id="twT1L">80 °C</b></span>
          <input type="range" id="twT1" min="0" max="100" step="5" value="80" oninput="_twSet('T1',this.value)" style="width:100%;accent-color:#ef4444"></div>
        <div class="fpm-label" style="margin-top:8px">Gefäß 2 (rechts)</div>
        <div class="phys-ctrl"><span class="phys-ctrl-label">Menge: <b id="twM2L">2 L</b></span>
          <input type="range" id="twM2" min="0.5" max="3" step="0.5" value="2" oninput="_twSet('m2',this.value)" style="width:100%;accent-color:#7c3aed"></div>
        <div class="phys-ctrl" style="margin-top:4px"><span class="phys-ctrl-label">Temperatur: <b id="twT2L">20 °C</b></span>
          <input type="range" id="twT2" min="0" max="100" step="5" value="20" oninput="_twSet('T2',this.value)" style="width:100%;accent-color:#ef4444"></div>
        <div class="lmp-status" id="twStatus" style="margin-top:8px"></div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>Temperatur</b> (°C) = wie warm. &nbsp;|&nbsp; <b>Wärme</b> = übertragene Energie (hängt von Menge UND Temperatur ab). Wärme fließt vom Warmen zum Kalten.
    </p>
    ${_twArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _twSet(k, v) {
  _tw[k] = +v;
  const map = { m1: 'twM1L', T1: 'twT1L', m2: 'twM2L', T2: 'twT2L' };
  const unit = (k[0] === 'm') ? ' L' : ' °C';
  const el = document.getElementById(map[k]); if (el) el.textContent = _fpmNum(+v, k[0] === 'm' ? 1 : 0) + unit;
  if (k === 'T1') _tw.a1 = +v; if (k === 'T2') _tw.a2 = +v;
  _tw.mixed = false; _twStatus();
}
function _twContact() { _tw.mixed = true; _tw.a1 = _tw.T1; _tw.a2 = _tw.T2; _twStatus(); }
function _twReset() { _twInit(); _twStatus(); for (const k of ['m1', 'T1', 'm2', 'T2']) { const sl = document.getElementById('tw' + (k[0] === 'm' ? 'M' + k[1] : 'T' + k[1])); } }
function _twStatus() {
  const el = document.getElementById('twStatus'); if (!el) return;
  const W1 = _twWaerme(_tw.m1, _tw.T1), W2 = _twWaerme(_tw.m2, _tw.T2);
  if (_tw.mixed) { el.textContent = '🔗 Wärme fließt vom Warmen zum Kalten → Mischtemperatur ≈ ' + _fpmNum(_twMix(), 0) + ' °C.'; el.className = 'lmp-status on'; }
  else {
    const more = W1 > W2 ? 'Gefäß 1' : (W2 > W1 ? 'Gefäß 2' : 'beide gleich');
    el.textContent = 'Wärmemenge: Gefäß 1 = ' + _fpmNum(W1, 0) + ', Gefäß 2 = ' + _fpmNum(W2, 0) + ' Einheiten → mehr Wärme: ' + more + '.';
    el.className = 'lmp-status';
  }
}

// ── Animation ──────────────────────────────────────────
function _twUpdate(dt) {
  if (!_tw) return; _tw.t += dt;
  if (_tw.mixed) { const Tm = _twMix(); _tw.a1 += (Tm - _tw.a1) * Math.min(1, dt * 1.1); _tw.a2 += (Tm - _tw.a2) * Math.min(1, dt * 1.1); }
}
function _twCol(T) { const r = Math.round(60 + T * 1.9), b = Math.round(230 - T * 1.8); return `rgb(${r},${Math.round(120 - T * 0.3)},${b})`; }
function _twBeaker(ctx, x, y, w, h, m, T, W, label) {
  const fill = (m / 3) * h;
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2; ctx.strokeRect(x, y, w, h);
  ctx.fillStyle = _twCol(T); ctx.fillRect(x + 2, y + h - fill, w - 4, fill - 2);
  ctx.fillStyle = '#334155'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText(label, x + w / 2, y - 20);
  ctx.fillText(_fpmNum(T, 0) + ' °C', x + w / 2, y - 6);
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.fillText(_fpmNum(m, 1) + ' L', x + w / 2, y + h + 14);
  // Wärmemenge-Balken
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(x, y + h + 22, w, 8);
  ctx.fillStyle = '#f97316'; ctx.fillRect(x, y + h + 22, w * Math.min(1, W / 300), 8);
  ctx.fillStyle = '#92400e'; ctx.font = '9px sans-serif'; ctx.fillText('Wärme: ' + _fpmNum(W, 0), x + w / 2, y + h + 42);
}
function _twDraw(ctx, cv) {
  if (!_tw) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  const T1 = _tw.mixed ? _tw.a1 : _tw.T1, T2 = _tw.mixed ? _tw.a2 : _tw.T2;
  _twBeaker(ctx, 70, 60, 90, 110, _tw.m1, T1, _twWaerme(_tw.m1, _tw.T1), 'Gefäß 1');
  _twBeaker(ctx, 280, 60, 90, 110, _tw.m2, T2, _twWaerme(_tw.m2, _tw.T2), 'Gefäß 2');
  if (_tw.mixed) {
    const warmLeft = _tw.T1 > _tw.T2;
    ctx.strokeStyle = '#f97316'; ctx.lineWidth = 3; ctx.setLineDash([7, 5]); ctx.lineDashOffset = -(_tw.t * 50) % 12;
    ctx.beginPath(); ctx.moveTo(warmLeft ? 165 : 275, 115); ctx.lineTo(warmLeft ? 275 : 165, 115); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle = '#ea580c'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('Wärme fließt →', 220, 105);
  } else {
    ctx.fillStyle = '#94a3b8'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('getrennt', 220, 118);
  }
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 6.1.1  (ns = 'tempwaerme') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _twArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('tempwaerme')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('tempwaerme')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Sind Temperatur und Wärme dasselbe? Kann ein kleines heißes Gefäß weniger Wärme haben als ein großes warmes?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute: Temperatur und Wärme sind … Mehr Wärme hat …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Stelle Gefäß 1 auf <b>1 L, 80 °C</b> und Gefäß 2 auf <b>2 L, 20 °C</b>. Vergleiche Temperatur und Wärmemenge.</li>
          <li>Suche eine Einstellung, bei der das <b>kältere</b> Gefäß trotzdem <b>mehr Wärme</b> hat.</li>
          <li>Bring beide in Kontakt. In welche Richtung fließt die Wärme?</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td></td><td>Menge</td><td>Temperatur</td><td>Wärmemenge</td></tr>
          <tr><td>Gefäß 1</td><td>${inp('t1m', 'L')}</td><td>${inp('t1t', '°C')}</td><td>${inp('t1w', 'Einh.')}</td></tr>
          <tr><td>Gefäß 2</td><td>${inp('t2m', 'L')}</td><td>${inp('t2t', '°C')}</td><td>${inp('t2w', 'Einh.')}</td></tr>
          <tr><td>Nach Kontakt: Mischtemperatur</td><td colspan="3">${inp('tmix', '°C')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne die beiden Gefäße und einen Pfeil, in welche Richtung die Wärme fließt.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Wovon hängt die Wärmemenge ab? ${inp('a1', 'von … und …')}</li>
          <li>In welche Richtung fließt Wärme immer? ${inp('a2', 'vom … zum …')}</li>
          <li>Ist heißer immer gleich „mehr Wärme"? ${inp('a3', 'ja/nein, weil …')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Die <b>Temperatur</b> (in ${inp('m1', 'Einheit?')}) sagt, wie warm etwas ist.<br>
        Die <b>Wärme</b> ist übertragene ${inp('m2', 'was?')} und hängt von Menge und Temperatur ab.<br>
        Wärme fließt immer vom ${inp('m3', 'warmen/kalten')} zum kalten Körper.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Eine Wunderkerze sprüht Funken mit über 1000 °C – trotzdem tut ein Funke auf der Haut kaum weh. Eine Badewanne mit 40 °C wärmt dich dagegen lange. Erkläre den Unterschied.</div>
        ${ta('tr1', 'Der Funke ist sehr heiß, aber … Die Badewanne …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="twMini">${_twMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_twSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_twSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_twSelf(3)">😃 sicher</button>
          <span id="twSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="twSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> 1 L/80 °C hat Wärme 80 Einheiten, 2 L/20 °C hat 40 – hier ist das heißere Gefäß auch das energiereichere. Mit 3 L/40 °C (=120) gegen 1 L/90 °C (=90) hat das kältere Gefäß mehr Wärme. Bei Kontakt: Wärme fließt vom Warmen zum Kalten bis zur Mischtemperatur.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Temperatur ist eine Zustandsgröße (wie warm). Wärme ist übertragene Energie und hängt von Menge (Masse) und Temperatur ab. „Heiß" ≠ „viel Wärme". Wärme fließt stets vom wärmeren zum kälteren Körper.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Heißer = mehr Wärme, immer." (2) „Temperatur und Wärme sind dasselbe." (3) „Kälte fließt in den warmen Körper."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Wärmemenge-Balken (Menge × Temperatur) beobachten; Gegenbeispiel Badewanne vs. Funke; Fluss immer warm → kalt.</div>
        <div class="ab-t"><b>Musterlösung.</b> 6.1 „von Menge und Temperatur" · 6.2 „vom warmen zum kalten" · 6.3 „nein". Merksatz: °C · Energie · warmen. Transfer: Der Funke ist winzig → wenig Wärme trotz hoher Temperatur; die Badewanne enthält viel Wasser → viel Wärme trotz niedrigerer Temperatur. Minidiagnose: 1→°C · 2→„Menge und Temperatur" · 3→„vom warmen zum kalten".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('tempwaerme')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('tempwaerme', 'Sind Temperatur und Wärme das Gleiche?', body);
}

const _TW_MINI = [
  { q: '1. In welcher Einheit misst man die Temperatur?',
    opts: ['In Liter', 'In Grad Celsius (°C)', 'In Watt'], correct: 1,
    fb: ['Liter ist eine Menge, keine Temperatur.',
         'Richtig! Die Temperatur misst man in Grad Celsius.',
         'Watt ist eine Leistung.'] },
  { q: '2. Wovon hängt die Wärmemenge (Energie) ab?',
    opts: ['Nur von der Temperatur', 'Von Menge UND Temperatur', 'Nur von der Farbe'], correct: 1,
    fb: ['Die Menge zählt auch mit.',
         'Richtig! Die Wärmemenge hängt von Menge und Temperatur ab.',
         'Die Farbe spielt keine Rolle.'] },
  { q: '3. In welche Richtung fließt Wärme?',
    opts: ['Vom kalten zum warmen Körper', 'Vom warmen zum kalten Körper', 'Immer nach oben'], correct: 1,
    fb: ['Andersherum.',
         'Richtig! Wärme fließt immer vom warmen zum kalten Körper.',
         'Die Richtung hängt von der Temperatur ab, nicht von oben/unten.'] }
];
function _twMiniHTML() {
  return _TW_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_twAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="twFb${qi}"></div></div>`).join('');
}
function _twAns(qi, oi) {
  const m = _TW_MINI[qi], el = document.getElementById('twFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _twSelf(n) {
  const out = document.getElementById('twSelfOut'), val = document.getElementById('twSelfVal');
  if (val) { val.value = String(n); _abSave('tempwaerme'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 6.1.2  WIE FUNKTIONIERT EIN THERMOMETER?
// Realschule NRW – Klasse 6 · Inhaltsfeld "Sonnenenergie und Wärme"
// Handlungsorientiert: Die Flüssigkeit im Thermometer dehnt sich beim
// Erwärmen aus und steigt in der Röhre. Temperatur einstellen (oder
// Probe wählen), Flüssigkeitssäule beobachten, Wert an der Skala
// ablesen. Fixpunkte: 0 °C (Eiswasser), 100 °C (kochendes Wasser).
// ═══════════════════════════════════════════════════════

let _thm = null;
const _THM_MIN = -10, _THM_MAX = 110;
function _thmInit() { _thm = { T: 20, t: 0 }; }
const _THM_PROBEN = [
  { n: 'kalte Bretterwand', T: 6, ic: '🪵' },
  { n: 'Eiswasser', T: 0, ic: '🧊' },
  { n: 'Deine Faust', T: 37, ic: '✋' },
  { n: 'warmes Wasser', T: 45, ic: '💧' },
  { n: 'kochendes Wasser', T: 100, ic: '♨️' }
];

function _thmHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim thm-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🌡️ Wovon hängt es ab, wie weit der Faden im Thermometer steigt?</h3>
    <div class="fpm-note" style="margin-top:2px">Nimm das Thermometer von der Bretterwand der Bude. Stelle die Temperatur ein oder halte das Thermometer an einen der Orte – und beobachte den dünnen Faden. Lies jedes Mal den Wert an der Skala ab.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="thmAnim" width="440" height="260" class="phys-anim-cv"></canvas>
      </div>
      <div>
        <div class="fpm-label">Temperatur einstellen</div>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Temperatur: <b id="thmTLbl">20 °C</b></span>
          <input type="range" id="thmT" min="-10" max="110" step="1" value="20"
            oninput="_thmSetT(this.value)" style="width:100%;accent-color:#ef4444">
        </div>
        <div class="fpm-label" style="margin-top:10px">Oder Thermometer eintauchen in:</div>
        <div class="msf-chips" id="thmChips">${_thmChipsHTML()}</div>
        <div class="fpm-note" style="margin-top:10px">Lies immer auf <b>Augenhöhe</b> ab. Die Skala ist mit zwei Fixpunkten geeicht: <b>0 °C</b> (Eiswasser) und <b>100 °C</b> (kochendes Wasser).</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Warm → Flüssigkeit <b>dehnt sich aus</b> → steigt. &nbsp;|&nbsp; Kalt → Flüssigkeit zieht sich zusammen → fällt.
    </p>
    ${_thmArbeitsblattHTML()}
  </div>`;
}
function _thmChipsHTML() {
  return _THM_PROBEN.map((p, i) => `<button class="msf-chip" onclick="_thmProbe(${i})">${p.ic} ${p.n}</button>`).join('');
}

// ── Bedienung ──────────────────────────────────────────
function _thmSetT(v) { _thm.T = +v; const el = document.getElementById('thmTLbl'); if (el) el.textContent = _fpmNum(+v, 0) + ' °C'; }
function _thmProbe(i) { const p = _THM_PROBEN[i]; _thmSetT(p.T); const sl = document.getElementById('thmT'); if (sl) sl.value = p.T; }

// ── Animation ──────────────────────────────────────────
function _thmUpdate(dt) { if (_thm) _thm.t += dt; }
function _thmDraw(ctx, cv) {
  if (!_thm) return;
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  const tx = 120, bulbY = H - 40, topY = 30, tubeW = 14;
  // Röhre
  ctx.fillStyle = '#e2e8f0'; ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.roundRect ? ctx.roundRect(tx - tubeW / 2, topY, tubeW, bulbY - topY, 7) : ctx.rect(tx - tubeW / 2, topY, tubeW, bulbY - topY); ctx.fill(); ctx.stroke();
  ctx.beginPath(); ctx.arc(tx, bulbY, 18, 0, 2 * Math.PI); ctx.fillStyle = '#e2e8f0'; ctx.fill(); ctx.stroke();
  // Flüssigkeitssäule (Ausdehnung ~ Temperatur)
  const frac = (_thm.T - _THM_MIN) / (_THM_MAX - _THM_MIN);
  const levelY = bulbY - frac * (bulbY - topY - 6);
  ctx.fillStyle = '#ef4444';
  ctx.beginPath(); ctx.arc(tx, bulbY, 13, 0, 2 * Math.PI); ctx.fill();
  ctx.fillRect(tx - 4, levelY, 8, bulbY - levelY);
  // Skala
  ctx.strokeStyle = '#334155'; ctx.fillStyle = '#334155'; ctx.font = '10px sans-serif'; ctx.textAlign = 'left'; ctx.lineWidth = 1;
  for (let T = 0; T <= 100; T += 10) {
    const y = bulbY - ((T - _THM_MIN) / (_THM_MAX - _THM_MIN)) * (bulbY - topY - 6);
    const long = (T % 20 === 0);
    ctx.beginPath(); ctx.moveTo(tx + 10, y); ctx.lineTo(tx + 10 + (long ? 12 : 6), y); ctx.stroke();
    if (long) ctx.fillText(T + '', tx + 26, y + 3);
  }
  // Fixpunkte markieren
  ctx.fillStyle = '#2563eb'; ctx.font = '9px sans-serif';
  const y0 = bulbY - ((0 - _THM_MIN) / (_THM_MAX - _THM_MIN)) * (bulbY - topY - 6);
  ctx.fillText('0 °C Eiswasser', tx + 44, y0 + 3);
  ctx.fillStyle = '#dc2626';
  const y100 = bulbY - ((100 - _THM_MIN) / (_THM_MAX - _THM_MIN)) * (bulbY - topY - 6);
  ctx.fillText('100 °C kochend', tx + 44, y100 + 3);
  // Anzeige
  ctx.fillStyle = '#0f172a'; ctx.font = '700 20px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText(_fpmNum(_thm.T, 0) + ' °C', W - 90, 60);
  ctx.fillStyle = '#64748b'; ctx.font = '11px sans-serif';
  ctx.fillText(_thm.T > 30 ? 'Säule steigt (Ausdehnung)' : (_thm.T < 5 ? 'Säule fällt (Zusammenziehen)' : 'gemäßigt'), W - 90, 80);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 6.1.2  (ns = 'thermometer') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _thmArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('thermometer')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('thermometer')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wie zeigt ein Thermometer die Temperatur an?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute, die Flüssigkeit im Thermometer steigt, wenn …', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Erhöhe die Temperatur langsam. Was macht die Flüssigkeitssäule?</li>
          <li>Senke die Temperatur unter 0 °C. Was passiert jetzt?</li>
          <li>Tauche das Thermometer in verschiedene Proben und lies jeweils ab.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Eiswasser</td><td>${inp('t_eis', '°C')}</td><td>Zimmer</td><td>${inp('t_zim', '°C')}</td></tr>
          <tr><td>handwarm</td><td>${inp('t_hand', '°C')}</td><td>kochendes Wasser</td><td>${inp('t_koch', '°C')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne ein Thermometer bei niedriger und bei hoher Temperatur. Zeige die unterschiedliche Höhe der Säule.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Warum steigt die Flüssigkeit beim Erwärmen? ${inp('a1', 'weil sie sich …')}</li>
          <li>Was bedeuten die Fixpunkte 0 °C und 100 °C? ${inp('a2', '')}</li>
          <li>Wie liest man richtig ab? ${inp('a3', 'auf …')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Beim Erwärmen ${inp('m1', 'dehnt sich aus / zieht sich zusammen')} die Flüssigkeit und steigt in der Röhre.<br>
        Die Temperatur liest man an der ${inp('m2', 'was?')} in ${inp('m3', 'Einheit?')} ab.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Ein Fieberthermometer misst nur zwischen etwa 35 °C und 42 °C, dafür sehr genau. Warum braucht man beim Fiebermessen keinen großen Bereich wie 0–100 °C?</div>
        ${ta('tr1', 'Beim Fieber reicht ein kleiner Bereich, weil …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="thmMini">${_thmMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_thmSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_thmSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_thmSelf(3)">😃 sicher</button>
          <span id="thmSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="thmSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Steigende Temperatur → Säule steigt; unter 0 °C → Säule fällt. Ablesewerte: Eiswasser 0 °C, Zimmer ~21 °C, handwarm ~37 °C, kochend 100 °C.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Thermometer nutzen die Wärmeausdehnung einer Flüssigkeit (früher Quecksilber, heute meist gefärbter Alkohol). Geeicht wird an zwei Fixpunkten (0 °C Eis, 100 °C siedendes Wasser bei Normaldruck). Ablesen auf Augenhöhe vermeidet Parallaxenfehler.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Die Flüssigkeit wird mehr." (Es dehnt sich nur aus, die Menge bleibt gleich.) (2) „Das Thermometer erzeugt Wärme." (3) Ablesen schräg von oben.</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Ausdehnung als „mehr Platz je Teilchen" veranschaulichen; Fixpunkte betonen; Augenhöhe demonstrieren.</div>
        <div class="ab-t"><b>Musterlösung.</b> 6.1 „ausdehnt" · 6.2 „geeichte Fixpunkte Eis/kochend" · 6.3 „auf Augenhöhe". Merksatz: dehnt sich aus · Skala · °C. Transfer: Die Körpertemperatur liegt immer nahe 37 °C, ein kleiner, feiner Bereich genügt. Minidiagnose: 1→„sie dehnt sich aus" · 2→°C · 3→„auf Augenhöhe".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('thermometer')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('thermometer', 'Wie funktioniert ein Thermometer?', body);
}

const _THM_MINI = [
  { q: '1. Warum steigt die Flüssigkeit im Thermometer beim Erwärmen?',
    opts: ['Weil sie sich ausdehnt', 'Weil mehr Flüssigkeit entsteht', 'Weil sie leichter wird'], correct: 0,
    fb: ['Richtig! Beim Erwärmen dehnt sich die Flüssigkeit aus und steigt.',
         'Die Menge bleibt gleich – sie dehnt sich nur aus.',
         'Am Gewicht liegt es nicht.'] },
  { q: '2. In welcher Einheit liest man die Temperatur ab?',
    opts: ['In Grad Celsius (°C)', 'In Zentimeter', 'In Liter'], correct: 0,
    fb: ['Richtig! Die Temperatur misst man in Grad Celsius.',
         'Zentimeter misst Längen.',
         'Liter misst Mengen.'] },
  { q: '3. Wie liest man ein Thermometer richtig ab?',
    opts: ['Schräg von oben', 'Auf Augenhöhe', 'Von unten'], correct: 1,
    fb: ['Schräg liest man falsch ab.',
         'Richtig! Auf Augenhöhe liest man genau ab.',
         'Von unten verschätzt man sich.'] }
];
function _thmMiniHTML() {
  return _THM_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_thmAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="thmFb${qi}"></div></div>`).join('');
}
function _thmAns(qi, oi) {
  const m = _THM_MINI[qi], el = document.getElementById('thmFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _thmSelf(n) {
  const out = document.getElementById('thmSelfOut'), val = document.getElementById('thmSelfVal');
  if (val) { val.value = String(n); _abSave('thermometer'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 6.1.3  WAS GESCHIEHT BEIM ERWÄRMEN VON STOFFEN?
// Realschule NRW – Klasse 6 · Inhaltsfeld "Sonnenenergie und Wärme"
// Handlungsorientiert: Festkörper, Flüssigkeit und Gas erwärmen. Die
// Teilchen bewegen sich schneller und brauchen mehr Platz → der Stoff
// dehnt sich aus. Gase dehnen sich am stärksten aus. Teilchenmodell.
// ═══════════════════════════════════════════════════════

let _wau = null;
const _WAU_STATE = {
  fest:     { n: 'Festkörper (Metallstab)', coef: 0.12, cols: 6, rows: 4, jit: 3 },
  fluessig: { n: 'Flüssigkeit (Wasser)',    coef: 0.30, cols: 5, rows: 4, jit: 6 },
  gas:      { n: 'Gas (Luft)',              coef: 1.10, cols: 3, rows: 3, jit: 16 }
};
function _wauInit() { _wau = { state: 'fest', T: 20, t: 0 }; }
function _wauCoef() { return _WAU_STATE[_wau.state].coef; }
function _wauFactor() { return 1 + _wauCoef() * _wau.T / 100; }   // Ausdehnung (relativ)

function _wauHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim wau-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🌡️➡️ Wovon hängt es ab, ob sich der Deckel leicht aufdrehen lässt?</h3>
    <div class="fpm-note" style="margin-top:2px">Ein Blechdeckel klemmt auf dem Glas. Erwärme den Stoff mit dem Regler und beobachte, wie groß er dabei wird. Kühle es danach wieder ab. Prüfe zum Schluss, ob es bei Flüssigkeit und Gas genauso ist.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="wauAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn${_wau.state === 'fest' ? ' primary' : ''}" id="wauS0" onclick="_wauSetState('fest')">🧱 fest</button>
          <button class="sim-btn${_wau.state === 'fluessig' ? ' primary' : ''}" id="wauS1" onclick="_wauSetState('fluessig')">💧 flüssig</button>
          <button class="sim-btn${_wau.state === 'gas' ? ' primary' : ''}" id="wauS2" onclick="_wauSetState('gas')">💨 Gas</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Temperatur einstellen</div>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Temperatur: <b id="wauTLbl">20 °C</b></span>
          <input type="range" id="wauT" min="0" max="100" step="5" value="20"
            oninput="_wauSetT(this.value)" style="width:100%;accent-color:#ef4444">
        </div>
        <div class="lmp-status" id="wauStatus"></div>
        <div class="fpm-note" style="margin-top:10px"><b>Beobachte genau:</b> Wie groß ist der Balken „Größe des Stoffs" bei 20 °C, wie bei 90 °C? Und was passiert, wenn du wieder auf 20 °C zurückgehst?</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Warm → Teilchen schneller → mehr Platz → <b>Ausdehnung</b>. &nbsp;|&nbsp; Kalt → Teilchen langsamer → <b>Zusammenziehen</b>.
    </p>
    ${_wauArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _wauSetT(v) {
  _wau.T = +v; const el = document.getElementById('wauTLbl'); if (el) el.textContent = _fpmNum(+v, 0) + ' °C'; _wauStatus();
}
function _wauSetState(s) {
  _wau.state = s;
  for (const [i, k] of ['fest', 'fluessig', 'gas'].entries()) document.getElementById('wauS' + i)?.classList.toggle('primary', k === s);
  _wauStatus();
}
function _wauStatus() {
  const el = document.getElementById('wauStatus'); if (!el) return;
  const pct = (_wauFactor() - 1) * 100;
  el.textContent = _WAU_STATE[_wau.state].n + ': Ausdehnung ≈ ' + _fpmNum(pct, 0) + ' % (bei ' + _fpmNum(_wau.T, 0) + ' °C).';
  el.className = 'lmp-status ' + (_wau.T > 40 ? 'on' : '');
}

// ── Animation ──────────────────────────────────────────
function _wauUpdate(dt) { if (_wau) _wau.t += dt; }
function _wauDraw(ctx, cv) {
  if (!_wau) return;
  const W = cv.width, H = cv.height, cfg = _WAU_STATE[_wau.state], f = _wauFactor();
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  // Teilchenbox
  const bx = 40, by = 40, bw = 180, bh = 160;
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2; ctx.strokeRect(bx, by, bw, bh);
  ctx.fillStyle = '#475569'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('Teilchen', bx + bw / 2, by - 8);
  const amp = cfg.jit * (0.3 + _wau.T / 100), spread = Math.min(1, 0.4 + _wau.T / 130);
  const cols = cfg.cols, rows = cfg.rows;
  const gw = (bw - 30) * (_wau.state === 'gas' ? spread + 0.3 : 1), gh = (bh - 30) * (_wau.state === 'gas' ? spread + 0.3 : 1);
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const idx = r * cols + c;
    const baseX = bx + 15 + (cols > 1 ? gw * c / (cols - 1) : gw / 2);
    const baseY = by + 15 + (rows > 1 ? gh * r / (rows - 1) : gh / 2);
    const jx = Math.sin(_wau.t * (2 + _wau.T / 30) + idx * 1.3) * amp;
    const jy = Math.cos(_wau.t * (2 + _wau.T / 25) + idx * 0.9) * amp;
    ctx.fillStyle = _wau.T > 55 ? '#ef4444' : (_wau.T > 25 ? '#f97316' : '#3b82f6');
    ctx.beginPath(); ctx.arc(baseX + jx, baseY + jy, 6, 0, 2 * Math.PI); ctx.fill();
  }
  // Makroskopische Ausdehnung (Balken)
  const mx = 260, my = 70, mw0 = 120, mh0 = 26;
  ctx.fillStyle = '#475569'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'left'; ctx.fillText('Größe des Stoffs:', mx, my - 12);
  ctx.strokeStyle = '#cbd5e1'; ctx.setLineDash([4, 3]); ctx.strokeRect(mx, my, mw0 * (1 + cfg.coef), mh0); ctx.setLineDash([]);
  ctx.fillStyle = '#7c3aed'; ctx.fillRect(mx, my, mw0 * f, mh0);
  ctx.fillStyle = '#fff'; ctx.font = '700 11px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('+' + _fpmNum((f - 1) * 100, 0) + ' %', mx + mw0 * f / 2, my + 17);
  // Vergleichsbalken der drei Zustände bei aktueller Temperatur
  ctx.textAlign = 'left'; ctx.font = '10px sans-serif';
  const comp = [['fest', '#3b82f6'], ['fluessig', '#06b6d4'], ['gas', '#ef4444']];
  comp.forEach((cc, i) => {
    const cf = 1 + _WAU_STATE[cc[0]].coef * _wau.T / 100;
    const yy = my + 60 + i * 24;
    ctx.fillStyle = '#94a3b8'; ctx.fillText(_WAU_STATE[cc[0]].n.split(' ')[0], mx - 0, yy - 2);
    ctx.fillStyle = cc[1]; ctx.fillRect(mx + 54, yy - 11, 90 * (cf - 1) / 1.1 + 4, 12);
  });
  ctx.fillStyle = '#64748b'; ctx.font = '9px sans-serif'; ctx.fillText('Ausdehnung bei ' + _fpmNum(_wau.T, 0) + ' °C', mx, my + 60 + 3 * 24 + 4);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 6.1.3  (ns = 'ausdehnung') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _wauArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('ausdehnung')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('ausdehnung')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Was passiert mit einem Stoff und seinen Teilchen, wenn man ihn erwärmt?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute: Beim Erwärmen wird der Stoff … und die Teilchen …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Wähle den <b>Festkörper</b> und erhöhe die Temperatur. Beobachte Teilchen und Größe.</li>
          <li>Wiederhole das mit <b>Flüssigkeit</b> und <b>Gas</b> bei gleicher Temperatur.</li>
          <li>Vergleiche: Welcher Stoff dehnt sich am meisten aus?</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Stoff</td><td>Ausdehnung bei 100 °C</td></tr>
          <tr><td>Festkörper</td><td>${inp('t_fest', 'wenig/mittel/viel')}</td></tr>
          <tr><td>Flüssigkeit</td><td>${inp('t_fl', '')}</td></tr>
          <tr><td>Gas</td><td>${inp('t_gas', '')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne die Teilchen bei niedriger und bei hoher Temperatur. Zeige, dass sie mehr Platz brauchen.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung</div>
        <ol class="ab-ol">
          <li>Was machen die Teilchen beim Erwärmen? ${inp('a1', 'sie bewegen sich … und brauchen …')}</li>
          <li>Welcher Stoff dehnt sich am stärksten aus? ${inp('a2', '')}</li>
          <li>Was passiert beim Abkühlen? ${inp('a3', '')}</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Beim Erwärmen bewegen sich die Teilchen ${inp('m1', 'schneller/langsamer')} und brauchen mehr Platz → der Stoff ${inp('m2', 'dehnt sich aus / zieht sich zusammen')}.<br>
        Am stärksten dehnen sich ${inp('m3', 'welche Stoffe?')} aus.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Brücken haben in der Fahrbahn kleine Lücken (Dehnungsfugen), und Stromleitungen hängen im Sommer stärker durch. Erkläre beides mit der Wärmeausdehnung.</div>
        ${ta('tr1', 'Dehnungsfugen braucht man, weil … Stromleitungen …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="wauMini">${_wauMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_wauSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_wauSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_wauSelf(3)">😃 sicher</button>
          <span id="wauSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="wauSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> Alle drei Stoffe dehnen sich beim Erwärmen aus; die Teilchen bewegen sich schneller (stärkere thermische Bewegung) und rücken auseinander. Reihenfolge der Ausdehnung: Gas ≫ Flüssigkeit > Festkörper.</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Wärme erhöht die Teilchenbewegung → mittlerer Abstand wächst → Volumen/Länge nimmt zu (Wärmeausdehnung). Gase dehnen sich am stärksten aus, weil ihre Teilchen ohnehin frei beweglich sind. Die Teilchenzahl bleibt konstant.</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Die Teilchen selbst werden größer." (2) „Es kommen Teilchen dazu." (3) „Feste Stoffe dehnen sich gar nicht aus."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Betonen: nicht die Teilchen wachsen, sondern die Abstände; Gas/Flüssigkeit/Fest bei gleicher Temperatur vergleichen; Alltagsbeispiele (Bimetall, Dehnungsfuge).</div>
        <div class="ab-t"><b>Musterlösung.</b> 6.1 „schneller / mehr Platz" · 6.2 „Gase" · 6.3 „zieht sich zusammen". Merksatz: schneller · dehnt sich aus · Gase. Transfer: Dehnungsfugen geben der sich ausdehnenden Fahrbahn Platz; warme Leitungen werden länger und hängen durch. Minidiagnose: 1→„schneller, mehr Platz" · 2→Gas · 3→„Dehnungsfuge/Ausdehnung".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('ausdehnung')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('ausdehnung', 'Was geschieht beim Erwärmen von Stoffen?', body);
}

const _WAU_MINI = [
  { q: '1. Was machen die Teilchen, wenn man einen Stoff erwärmt?',
    opts: ['Sie werden größer', 'Sie bewegen sich schneller und brauchen mehr Platz', 'Sie verschwinden'], correct: 1,
    fb: ['Die Teilchen selbst werden nicht größer.',
         'Richtig! Sie bewegen sich schneller und brauchen mehr Platz → Ausdehnung.',
         'Sie bleiben erhalten, nur ihr Abstand wächst.'] },
  { q: '2. Welcher Stoff dehnt sich beim Erwärmen am stärksten aus?',
    opts: ['Festkörper', 'Flüssigkeit', 'Gas'], correct: 2,
    fb: ['Festkörper dehnen sich am wenigsten aus.',
         'Flüssigkeiten dehnen sich mittel aus.',
         'Richtig! Gase dehnen sich am stärksten aus.'] },
  { q: '3. Warum haben Brücken Dehnungsfugen (kleine Lücken)?',
    opts: ['Zum Sparen von Material', 'Damit die Fahrbahn sich bei Wärme ausdehnen kann', 'Für den Wasserablauf'], correct: 1,
    fb: ['Am Material sparen ist nicht der Grund.',
         'Richtig! Die warme Fahrbahn dehnt sich aus und braucht Platz.',
         'Es geht um die Wärmeausdehnung, nicht um Wasser.'] }
];
function _wauMiniHTML() {
  return _WAU_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_wauAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="wauFb${qi}"></div></div>`).join('');
}
function _wauAns(qi, oi) {
  const m = _WAU_MINI[qi], el = document.getElementById('wauFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _wauSelf(n) {
  const out = document.getElementById('wauSelfOut'), val = document.getElementById('wauSelfVal');
  if (val) { val.value = String(n); _abSave('ausdehnung'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 6.1.4  WIE VERÄNDERN SICH AGGREGATZUSTÄNDE?
// Realschule NRW – Klasse 6 · Inhaltsfeld "Sonnenenergie und Wärme"
// Handlungsorientiert: Wasser von −20 °C bis 120 °C erwärmen/abkühlen.
// fest (Eis) – flüssig (Wasser) – gasförmig (Dampf). Übergänge:
// Schmelzen/Erstarren bei 0 °C, Verdampfen/Kondensieren bei 100 °C.
// Teilchenmodell: fest = geordnet, flüssig = dicht+beweglich, gas = frei.
// ═══════════════════════════════════════════════════════

let _agg = null;
function _aggInit() { _agg = { T: 20, t: 0 }; }
function _aggState() { return _agg.T <= 0 ? 'fest' : (_agg.T >= 100 ? 'gas' : 'fluessig'); }

function _aggHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim agg-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🧊💧💨 Wovon hängt es ab, ob das Eis fest bleibt oder zu Wasser wird?</h3>
    <div class="fpm-note" style="margin-top:2px">Über Nacht ist die Wasserflasche in der Bude gefroren. Stelle die Temperatur ein – von der eiskalten Bude bis dicht neben die Kerze – und beobachte, was aus dem Eis wird.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="aggAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn" onclick="_aggStep(-15)">❄️ abkühlen</button>
          <button class="sim-btn" onclick="_aggStep(15)">🔥 erwärmen</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Temperatur einstellen</div>
        <div class="phys-ctrl" style="margin-top:6px">
          <span class="phys-ctrl-label">Temperatur: <b id="aggTLbl">20 °C</b></span>
          <input type="range" id="aggT" min="-20" max="120" step="5" value="20"
            oninput="_aggSetT(this.value)" style="width:100%;accent-color:#ef4444">
        </div>
        <div class="lmp-status" id="aggStatus"></div>
        <div class="fpm-note" style="margin-top:10px"><b>Suche selbst:</b> Bei welcher Zahl auf der Skala wird aus dem Eis Wasser? Und bei welcher Zahl wird aus dem Wasser wieder Eis? Notiere beide Werte.</div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      Trage in deine Tabelle ein: Wo liegt das Eis – und ist es dort nach 10 Minuten noch fest oder schon flüssig?
    </p>
    ${_aggArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _aggSetT(v) { _agg.T = +v; const el = document.getElementById('aggTLbl'); if (el) el.textContent = _fpmNum(+v, 0) + ' °C'; _aggStatus(); }
function _aggStep(d) {
  _agg.T = Math.max(-20, Math.min(120, _agg.T + d));
  const sl = document.getElementById('aggT'); if (sl) sl.value = _agg.T;
  _aggSetT(_agg.T);
}
function _aggStatus() {
  const el = document.getElementById('aggStatus'); if (!el) return;
  const s = _aggState();
  const txt = s === 'fest' ? '🧊 Eis – fest (Teilchen sitzen fest in einem Gitter).'
    : s === 'gas' ? '💨 Wasserdampf – gasförmig (Teilchen fliegen frei und schnell).'
      : '💧 Wasser – flüssig (Teilchen dicht beieinander, aber beweglich).';
  el.textContent = txt; el.className = 'lmp-status ' + (s === 'gas' ? 'off' : 'on');
}

// ── Animation ──────────────────────────────────────────
function _aggUpdate(dt) { if (_agg) _agg.t += dt; }
function _aggDraw(ctx, cv) {
  if (!_agg) return;
  const W = cv.width, H = cv.height, s = _aggState();
  ctx.clearRect(0, 0, W, H); ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
  // Teilchenbox
  const bx = 40, by = 30, bw = 200, bh = 150;
  ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2; ctx.strokeRect(bx, by, bw, bh);
  const N = s === 'gas' ? 10 : 24;
  const amp = s === 'fest' ? 2 : (s === 'fluessig' ? 6 : 20);
  const spd = s === 'fest' ? 3 : (s === 'fluessig' ? 5 : 9);
  for (let i = 0; i < N; i++) {
    let baseX, baseY;
    if (s === 'fest') { const c = i % 6, r = Math.floor(i / 6); baseX = bx + 26 + c * 30; baseY = by + 24 + r * 34; }
    else if (s === 'fluessig') { const c = i % 6, r = Math.floor(i / 6); baseX = bx + 24 + c * 30 + (r % 2) * 8; baseY = by + bh - 90 + r * 26; }
    else { baseX = bx + 20 + ((i * 53) % (bw - 40)); baseY = by + 20 + ((i * 37) % (bh - 40)); }
    const jx = Math.sin(_agg.t * spd + i * 1.7) * amp, jy = Math.cos(_agg.t * spd + i * 1.1) * amp;
    ctx.fillStyle = s === 'fest' ? '#3b82f6' : (s === 'fluessig' ? '#06b6d4' : '#ef4444');
    ctx.beginPath(); ctx.arc(baseX + jx, baseY + jy, 6, 0, 2 * Math.PI); ctx.fill();
    if (s === 'fest') { ctx.strokeStyle = 'rgba(59,130,246,0.3)'; ctx.lineWidth = 1; ctx.strokeRect(baseX - 12, baseY - 12, 24, 24); }
  }
  // Zustandsanzeige
  ctx.fillStyle = '#0f172a'; ctx.font = '700 15px sans-serif'; ctx.textAlign = 'left';
  ctx.fillText(s === 'fest' ? '🧊 fest (Eis)' : s === 'gas' ? '💨 gasförmig (Dampf)' : '💧 flüssig (Wasser)', 260, 44);
  // Temperaturskala mit Übergängen
  const sx = 260, sw = 150, sy = 90;
  ctx.fillStyle = '#e2e8f0'; ctx.fillRect(sx, sy, sw, 14);
  const frac = (_agg.T + 20) / 140;
  ctx.fillStyle = '#7c3aed'; ctx.fillRect(sx, sy, sw * frac, 14);
  // Marker 0 und 100
  [[0, 'Schmelzen 0 °C'], [100, 'Sieden 100 °C']].forEach(m => {
    const fx = sx + sw * (m[0] + 20) / 140;
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(fx, sy - 4); ctx.lineTo(fx, sy + 18); ctx.stroke();
    ctx.fillStyle = '#334155'; ctx.font = '8px sans-serif'; ctx.textAlign = 'center'; ctx.fillText(m[1], fx, sy + 30);
  });
  ctx.fillStyle = '#7c3aed'; ctx.font = '700 12px sans-serif'; ctx.textAlign = 'left'; ctx.fillText(_fpmNum(_agg.T, 0) + ' °C', sx, sy - 8);
  ctx.fillStyle = '#64748b'; ctx.font = '9px sans-serif';
  ctx.fillText('fest  ·  flüssig  ·  gasförmig', sx, sy + 46);
}

// ═══════════════════════════════════════════════════════
// ARBEITSBLATT 6.1.4  (ns = 'aggregat') – im 0123-Gate
// ═══════════════════════════════════════════════════════
function _aggArbeitsblattHTML() {
  const ta = (k, ph, rows) => `<textarea class="ab-field" data-abk="${k}" rows="${rows || 2}" placeholder="${ph}" oninput="_abSave('aggregat')"></textarea>`;
  const inp = (k, ph) => `<input class="ab-field ab-inline" data-abk="${k}" placeholder="${ph}" oninput="_abSave('aggregat')">`;
  const body = `
      <div class="ab-sec"><div class="ab-h">1 · Forscherfrage</div>
        <div class="ab-t"><b>Wie wird aus Eis Wasser und aus Wasser Dampf – und was tun dabei die Teilchen?</b></div></div>

      <div class="ab-sec"><div class="ab-h">2 · Meine Vermutung</div>
        ${ta('v1', 'Ich vermute: Eis wird bei … °C zu Wasser, Wasser bei … °C zu Dampf.', 2)}</div>

      <div class="ab-sec"><div class="ab-h">3 · Durchführung</div>
        <ol class="ab-ol">
          <li>Kühle das Wasser unter 0 °C. Welcher Zustand? Wie sitzen die Teilchen?</li>
          <li>Erwärme langsam über 0 °C und dann über 100 °C. Beobachte die Übergänge.</li>
          <li>Notiere, bei welcher Temperatur sich der Zustand ändert.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">4 · Beobachtungstabelle</div>
        <table class="ab-table"><tbody>
          <tr><td>Temperatur</td><td>Zustand</td><td>Teilchen</td></tr>
          <tr><td>−10 °C</td><td>${inp('t_a', 'fest/flüssig/gasförmig')}</td><td>${inp('t_at', 'geordnet/…')}</td></tr>
          <tr><td>50 °C</td><td>${inp('t_b', '')}</td><td>${inp('t_bt', '')}</td></tr>
          <tr><td>110 °C</td><td>${inp('t_c', '')}</td><td>${inp('t_ct', '')}</td></tr>
        </tbody></table></div>

      <div class="ab-sec"><div class="ab-h">5 · Skizze</div>
        <div class="ab-t">Zeichne die Teilchen im festen, flüssigen und gasförmigen Zustand.</div>
        <div class="ab-skizze">Platz für deine Skizze</div></div>

      <div class="ab-sec"><div class="ab-h">6 · Auswertung – Übergänge benennen</div>
        <ol class="ab-ol">
          <li>fest → flüssig heißt ${inp('a1', '?')} (bei 0 °C).</li>
          <li>flüssig → gasförmig heißt ${inp('a2', '?')} (bei 100 °C).</li>
          <li>gasförmig → flüssig heißt ${inp('a3', '?')}, flüssig → fest heißt ${inp('a4', '?')}.</li>
        </ol></div>

      <div class="ab-sec"><div class="ab-h">7 · Merksatz (ergänze die Lücken)</div>
        <div class="ab-t">Im <b>festen</b> Zustand sitzen die Teilchen ${inp('m1', 'geordnet/frei')}, im <b>flüssigen</b> sind sie dicht, aber beweglich, im <b>gasförmigen</b> fliegen sie ${inp('m2', 'wie?')}.<br>
        Wasser schmilzt bei ${inp('m3', '°C')} und siedet bei ${inp('m4', '°C')}.</div></div>

      <div class="ab-sec"><div class="ab-h">8 · Transfer (Alltag)</div>
        <div class="ab-t">Eine Pfütze trocknet in der Sonne, und eine kalte Brille beschlägt im warmen Raum. Welcher Übergang steckt jeweils dahinter?</div>
        ${ta('tr1', 'Die Pfütze trocknet durch … , die Brille beschlägt durch …', 3)}</div>

      <div class="ab-sec"><div class="ab-h">🔎 Minidiagnose – teste dich selbst</div>
        <div id="aggMini">${_aggMiniHTML()}</div></div>

      <div class="ab-sec"><div class="ab-h">🙂 Selbsteinschätzung</div>
        <div class="ab-t">Wie sicher fühlst du dich?</div>
        <div class="sha-self">
          <button class="sim-btn" onclick="_aggSelf(1)">😟 unsicher</button>
          <button class="sim-btn" onclick="_aggSelf(2)">😐 geht so</button>
          <button class="sim-btn" onclick="_aggSelf(3)">😃 sicher</button>
          <span id="aggSelfOut" class="sha-fb"></span>
        </div>
        <input type="hidden" class="ab-field" data-abk="self" id="aggSelfVal">
      </div>

      <details class="sha-lehrer">
        <summary>🔒 Nur für die Lehrkraft – Erwartungen &amp; Lösungen</summary>
        <div class="ab-t"><b>Erwartete Beobachtungen.</b> −10 °C fest (Teilchen geordnet), 50 °C flüssig (dicht, beweglich), 110 °C gasförmig (frei, schnell). Übergänge bei 0 °C (Schmelzen/Erstarren) und 100 °C (Verdampfen/Kondensieren).</div>
        <div class="ab-t"><b>Fachlich richtig.</b> Aggregatzustände hängen von der Teilchenbewegung ab. Schmelzen/Verdampfen brauchen Energie, Erstarren/Kondensieren geben Energie ab (in Kl. 6 qualitativ). Fixpunkte für Wasser: 0 °C und 100 °C (Normaldruck).</div>
        <div class="ab-t"><b>Mögliche Fehlvorstellungen.</b> (1) „Beim Schmelzen verschwinden Teilchen." (2) „Dampf ist die sichtbare Wolke" (der sichtbare Nebel ist bereits kondensiert). (3) „Erstarren = Verdampfen rückwärts."</div>
        <div class="ab-t"><b>Hilfestellungen.</b> Teilchenbilder der drei Zustände zeichnen lassen; Übergangsnamen paarweise (hin/zurück) lernen; Alltagsbezüge Pfütze/Brille.</div>
        <div class="ab-t"><b>Musterlösung.</b> 6.1 Schmelzen · 6.2 Verdampfen (Sieden) · 6.3 Kondensieren / Erstarren. Merksatz: geordnet · frei/schnell · 0 · 100. Transfer: Pfütze → Verdunsten/Verdampfen; Brille → Kondensieren. Minidiagnose: 1→Schmelzen · 2→Verdampfen · 3→„geordnet".</div>
      </details>

      <div class="sim-btn-row" style="margin-top:8px">
        <button class="sim-btn" onclick="_abClear('aggregat')">🗑 Protokoll zurücksetzen</button>
      </div>`;
  return _abWrap('aggregat', 'Wie verändern sich Aggregatzustände?', body);
}

const _AGG_MINI = [
  { q: '1. Wie heißt der Übergang von fest zu flüssig?',
    opts: ['Schmelzen', 'Verdampfen', 'Erstarren'], correct: 0,
    fb: ['Richtig! fest → flüssig heißt Schmelzen (bei 0 °C).',
         'Verdampfen ist flüssig → gasförmig.',
         'Erstarren ist genau andersherum (flüssig → fest).'] },
  { q: '2. Wie heißt der Übergang von flüssig zu gasförmig?',
    opts: ['Kondensieren', 'Verdampfen', 'Schmelzen'], correct: 1,
    fb: ['Kondensieren ist andersherum.',
         'Richtig! flüssig → gasförmig heißt Verdampfen (bei 100 °C).',
         'Schmelzen betrifft festes Eis.'] },
  { q: '3. Wie sind die Teilchen im festen Zustand angeordnet?',
    opts: ['Frei und schnell', 'Geordnet und fest an ihrem Platz', 'Es gibt keine Teilchen'], correct: 1,
    fb: ['Das gilt für Gase.',
         'Richtig! Im Festkörper sitzen die Teilchen geordnet an ihrem Platz.',
         'Teilchen gibt es in jedem Zustand.'] }
];
function _aggMiniHTML() {
  return _AGG_MINI.map((m, qi) =>
    `<div class="sha-q"><div class="sha-q-t">${m.q}</div>
       <div class="sha-opts">${m.opts.map((o, oi) => `<button class="sim-btn" onclick="_aggAns(${qi},${oi})">${o}</button>`).join('')}</div>
       <div class="sha-fb" id="aggFb${qi}"></div></div>`).join('');
}
function _aggAns(qi, oi) {
  const m = _AGG_MINI[qi], el = document.getElementById('aggFb' + qi); if (!el) return;
  const ok = oi === m.correct;
  el.textContent = (ok ? '✓ ' : '✗ ') + m.fb[oi]; el.className = 'sha-fb ' + (ok ? 'ok' : 'no');
}
function _aggSelf(n) {
  const out = document.getElementById('aggSelfOut'), val = document.getElementById('aggSelfVal');
  if (val) { val.value = String(n); _abSave('aggregat'); }
  if (out) out.textContent = n === 3 ? '✓ Super!' : (n === 2 ? 'Übe noch ein bisschen.' : 'Frag deine Lehrkraft – das schaffst du!');
}

// ═══════════════════════════════════════════════════════
// 6.1.5  WIE WIRD WÄRME ÜBERTRAGEN?
// Realschule NRW – Klasse 6 · Inhaltsfeld "Sonnenenergie und Wärme"
// Handlungsorientiert: drei Arten der Wärmeübertragung wählen und
// beobachten – Wärmeleitung (Kontakt, Metall), Wärmeströmung
// (Konvektion, warme Flüssigkeit/Luft steigt auf) und Wärmestrahlung
// (ohne Materie, z. B. Sonne).
// ═══════════════════════════════════════════════════════

let _wue = null;
const _WUE_MODE = {
  leitung:   { n: 'Wärmeleitung', ic: '🥄', d: 'Wärme wandert durch direkten Kontakt von Teilchen zu Teilchen – besonders gut in Metallen (z. B. der Löffel im heißen Tee).' },
  stroemung: { n: 'Wärmeströmung (Konvektion)', ic: '♨️', d: 'In Flüssigkeiten und Gasen steigt das warme, leichtere Material auf, das kalte sinkt ab – es entsteht eine Strömung (z. B. Heizung erwärmt den Raum).' },
  strahlung: { n: 'Wärmestrahlung', ic: '☀️', d: 'Wärme wird als Strahlung übertragen – ganz ohne Materie, sogar durch den leeren Raum (z. B. die Sonne wärmt die Erde).' }
};
function _wueInit() { _wue = { mode: 'leitung', t: 0 }; }

function _wueHTML() {
  return `<div class="sim-box sim-box-wide fpm-sim wue-sim">
    <button class="sim-x" onclick="closePhysicsSim()">✕</button>
    <h3 class="sim-h3">🔥 Auf welchen Wegen wandert Wärme von warm nach kalt?</h3>
    <div class="fpm-note" style="margin-top:2px">Auf der Kerze in der Bude steht ein Topf mit Tee. Wähle einen Weg aus und beobachte genau, wie sich die Wärme dabei bewegt. Vergleiche danach mit dem Löffel im Topf.</div>
    <div class="fpm-grid">
      <div>
        <canvas id="wueAnim" width="440" height="240" class="phys-anim-cv"></canvas>
        <div class="sim-btn-row" style="margin-top:6px">
          <button class="sim-btn${_wue.mode === 'leitung' ? ' primary' : ''}" id="wueM0" onclick="_wueSet('leitung')">🥄 Leitung</button>
          <button class="sim-btn${_wue.mode === 'stroemung' ? ' primary' : ''}" id="wueM1" onclick="_wueSet('stroemung')">♨️ Strömung</button>
          <button class="sim-btn${_wue.mode === 'strahlung' ? ' primary' : ''}" id="wueM2" onclick="_wueSet('strahlung')">☀️ Strahlung</button>
        </div>
      </div>
      <div>
        <div class="fpm-label">Das passiert gerade</div>
        <div class="wir-um" id="wueDesc" style="margin-top:6px"></div>
        <div class="fpm-label" style="margin-top:12px">Beispiele</div>
        <div class="fpm-note" style="margin-top:4px">
          🥄 <b>Leitung:</b> der Metalllöffel im Teetopf, Bügeleisen, Kochtopf.<br>
          ♨️ <b>Strömung:</b> Heizkörper, kochendes Wasser, Wind.<br>
          ☀️ <b>Strahlung:</b> Sonne, Lagerfeuer, Grill, Heizstrahler.
        </div>
      </div>
    </div>
    <p class="sim-hint" style="text-align:center;margin:6px 0 0">
      <b>Leitung</b> (Kontakt) &nbsp;|&nbsp; <b>Strömung</b> (warm steigt auf) &nbsp;|&nbsp; <b>Strahlung</b> (ohne Materie)
    </p>
    ${_wueArbeitsblattHTML()}
  </div>`;
}

// ── Bedienung ──────────────────────────────────────────
function _wueSet(m) {
  _wue.mode = m;
  for (const [i, k] of ['leitung', 'stroemung', 'strahlung'].entries()) document.getElementById('wueM' + i)?.classList.toggle('primary', k === m);
  const d = document.getElementById('wueDesc'); if (d) d.innerHTML = '<b>' + _WUE_MODE[m].ic + ' ' + _WUE_MODE[m].n + ':</b> ' + _WUE_MODE[m].d;
}

// ── Animation ──────────────────────────────────────────
function _wueUpdate(dt) { if (_wue) _wue.t += dt; }
function _wueDraw(ctx, cv) {
  if (!_wue) return;
  const W = cv.width, H = cv.height, m = _wue.mode, cy = H / 2;
  ctx.clearRect(0, 0, W, H);
  if (m === 'leitung') {
    ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, W, H);
    // Metallstab
    const rx = 70, rw = 300, ry = cy - 16;
    for (let i = 0; i < rw; i++) {
      const pos = i / rw;                      // 0 links (heiß) .. 1 rechts (kalt)
      const front = (_wue.t * 0.25) % 1.3;      // Wärmefront wandert
      const hot = Math.max(0, 1 - Math.abs(pos - Math.min(front, 1)) * 3 - pos * 0.5);
      const r = Math.round(120 + 135 * Math.min(1, hot + (1 - pos) * 0.6));
      ctx.fillStyle = `rgb(${r},${Math.round(120 - hot * 60)},${Math.round(160 - hot * 120)})`;
      ctx.fillRect(rx + i, ry, 1, 32);
    }
    ctx.strokeStyle = '#64748b'; ctx.lineWidth = 2; ctx.strokeRect(rx, ry, rw, 32);
    // Flamme links
    ctx.fillStyle = '#f97316'; ctx.beginPath(); ctx.moveTo(rx - 6, ry + 40); ctx.quadraticCurveTo(rx + 4, ry + 10, rx - 2, ry - 6); ctx.quadraticCurveTo(rx + 16, ry + 14, rx + 10, ry + 40); ctx.fill();
    ctx.fillStyle = '#334155'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('heiß', rx + 20, ry - 12); ctx.fillText('kalt', rx + rw - 20, ry - 12);
    ctx.fillText('Wärme wandert durch das Metall →', W / 2, ry + 60);
  } else if (m === 'stroemung') {
    ctx.fillStyle = '#eff6ff'; ctx.fillRect(0, 0, W, H);
    // Topf mit Wasser
    const px = 120, pw = 200, pt = 55, pb = H - 55;
    ctx.fillStyle = '#dbeafe'; ctx.fillRect(px, pt, pw, pb - pt);
    ctx.strokeStyle = '#64748b'; ctx.lineWidth = 3; ctx.strokeRect(px, pt, pw, pb - pt);
    // Flamme unten
    ctx.fillStyle = '#f97316'; for (let k = 0; k < 5; k++) { const fx = px + 30 + k * 35; ctx.beginPath(); ctx.moveTo(fx - 7, pb + 20); ctx.quadraticCurveTo(fx, pb + 2, fx, pb + 22); ctx.quadraticCurveTo(fx + 7, pb + 2, fx + 7, pb + 20); ctx.fill(); }
    // Konvektionspfeile (warm steigt Mitte, kalt sinkt außen)
    ctx.lineWidth = 3; ctx.strokeStyle = '#ef4444';
    const ph = ((_wue.t * 40) % (pb - pt - 20));
    ctx.beginPath(); ctx.moveTo(px + pw / 2, pb - 10 - ph); ctx.lineTo(px + pw / 2, pb - 20 - ph + 14); ctx.stroke();  // warm hoch
    ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(px + pw / 2, pb - 10 - ph, 5, 0, 2 * Math.PI); ctx.fill();
    ctx.strokeStyle = '#3b82f6'; ctx.fillStyle = '#3b82f6';
    ctx.beginPath(); ctx.arc(px + 30, pt + 20 + ph, 5, 0, 2 * Math.PI); ctx.fill();       // kalt runter
    ctx.beginPath(); ctx.arc(px + pw - 30, pt + 20 + ph, 5, 0, 2 * Math.PI); ctx.fill();
    // Umlauf-Pfeile
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(px + pw / 2 - 45, cy, 40, -Math.PI / 2, Math.PI / 2, true); ctx.stroke();
    ctx.beginPath(); ctx.arc(px + pw / 2 + 45, cy, 40, -Math.PI / 2, Math.PI / 2, false); ctx.stroke();
    ctx.fillStyle = '#334155'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('warmes Wasser steigt auf, kaltes sinkt', W / 2, pt - 12);
  } else {
    ctx.fillStyle = '#0f172a'; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('leerer Raum (keine Materie nötig)', W / 2, 24);
    // Sonne links
    ctx.fillStyle = '#facc15'; ctx.beginPath(); ctx.arc(70, cy, 26, 0, 2 * Math.PI); ctx.fill();
    // Strahlungswellen
    for (let k = 0; k < 5; k++) {
      const rad = 40 + ((_wue.t * 60 + k * 55) % 300);
      ctx.strokeStyle = `rgba(251,191,36,${Math.max(0, 0.7 - rad / 320)})`; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(70, cy, rad, -0.7, 0.7); ctx.stroke();
    }
    // Objekt rechts wird warm
    ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(W - 70, cy, 22, 0, 2 * Math.PI); ctx.fill();
    ctx.fillStyle = '#fca5a5'; ctx.font = '11px sans-serif'; ctx.fillText('wird warm', W - 70, cy + 40);
    ctx.fillStyle = '#fde047'; ctx.fillText('Sonne', 70, cy + 44);
  }
}

