  ctx.strokeStyle = 'rgba(196,181,253,0.55)';
  ctx.beginPath();
  ctx.moveTo(bx - eh * 0.71, by - eh * 0.71); ctx.lineTo(bx - 58, by - 58); ctx.stroke();
  ctx.strokeStyle = 'rgba(253,224,171,0.5)';
  ctx.beginPath();
  ctx.moveTo(bx + RP * 0.71, by - RP * 0.71); ctx.lineTo(bx + 56, by - 72); ctx.stroke();
  ctx.setLineDash([]);
  _wrText(ctx, bx - 62, by - 66, 'Ereignishorizont', { align: 'right', farbe: '#c4b5fd', font: '9px system-ui, sans-serif' });
  _wrText(ctx, bx + 60, by - 80, 'Licht läuft ums Loch herum', { align: 'left', farbe: '#fde68a', font: '9px system-ui, sans-serif' });

  // ── Lichtstrahl auf seiner wirklichen Bahn ──────────────────────────
