    ctx.beginPath(); ctx.moveTo(x, mb - 1); ctx.lineTo(x - 5, mb - 8); ctx.lineTo(x + 5, mb - 8); ctx.closePath(); ctx.fill();
    ctx.font = 'bold 13px sans-serif'; ctx.textAlign = 'center';
    const lx = Math.min(390, Math.max(x, 70));
