  ctx.textAlign = 'left'; ctx.font = 'bold 12px sans-serif';
  ctx.fillStyle = s.wind ? '#1d4ed8' : '#64748b';
  ctx.fillText(s.wind ? 'Wind' : 'kein Wind', 60, 20);
