    const y = 199 + i * 12.5;
    const da = _bji.gemessen[k] != null;
    ctx.fillStyle = da || k === h ? _BJI_FARBE[k] : '#cbd5e1';
    ctx.fillRect(224, y - 7, 10, 7);
    ctx.fillStyle = da ? '#0f172a' : (k === h ? '#334155' : '#94a3b8');
