  ctx.setLineDash([]);
  ctx.fillStyle = '#334155'; ctx.font = '700 10px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('herausgenommen', A.x + A.w / 2, A.y + 13, A.w - 8);
  ctx.restore();

  // Figur
  _bksHaut(ctx, P, false);
