    for (let x = _C8Q_CX - halb; x <= _C8Q_CX + halb + 0.1; x += 5) {
      plaetze.push({ x: x + (r % 2) * 2.5, y: _C8Q_BBOT - 6 - r * 4.2,
                     k: Math.abs(x - _C8Q_CX) / 50 + r * 0.8 });
    }
