    t: 0, salz: 100,
    phase: 'bereit',        // bereit · laeuft · fertig
    pt: 0,                  // s seit Start
    koerner: [], gestreut: 0, boden: 0, platzNr: 0,
    dreh: 0, drehV: 0,      // Rührstab: Winkel und Tempo
    plaetze, salzHaufen, z: _c8qZufall(7),
    fx: { teile: [] }, zeitlupe: null, fokus: null, erstesGezeigt: false,
    nach: -1, schritt: 0,
